['```c
#include <stdlib.h>
#include <assert.h>
#include <pthread.h>

typedef struct Record {
    int value;
} Record;

typedef struct HashTable {
    size_t capacity;
    size_t loadFactor;
    size_t count;
    pthread_mutex_t lock;
    long* offsets;
    int* keys;
    Record** records;
} HashTable;

typedef struct Config {
    size_t loadFactor;
} Config;

HashTable* createHashTable(size_t capacity, const Config* config) {
    assert(capacity > 0);

    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->offsets = calloc(capacity, sizeof(long));
    if (table->offsets == NULL) {
        free(table);
        return NULL;
    }

    table->keys = malloc(sizeof(int) * capacity);
    if (table->keys == NULL) {
        free(table->offsets);
        free(table);
        return NULL;
    }

    table->records = calloc(capacity, sizeof(Record*));
    if (table->records == NULL) {
        free(table->keys);
        free(table->offsets);
        free(table);
        return NULL;
    }

    table->count = 0;
    table->capacity = capacity;
    table->loadFactor = config->loadFactor;

    if (pthread_mutex_init(&table->lock, NULL) != 0) {
        free(table->records);
        free(table->keys);
        free(table->offsets);
        free(table);
        return NULL;
    }

    return table;
}

void insertRecord(HashTable* table, int key, Record* record) {
    assert(table != NULL);
    assert(record != NULL);

    pthread_mutex_lock(&table->lock);
    if (table->count >= table->capacity * table->loadFactor / 100) {
        // Handle capacity limit exceeded, e.g., by resizing the hash table
    } else {
        size_t index = ((size_t)key) % table->capacity;

        while (table->offsets[index] != 0) {
            index = (index + 1) % table->capacity;
        }

        table->keys[index] = key;
        table->records[index] = record;
        table->count++;
    }

    pthread_mutex_unlock(&table->lock);
}

Record* lookupRecord(HashTable* table, int key) {
    assert(table != NULL);

    size_t index = ((size_t)key) % table->capacity;

    pthread_mutex_lock(&table->lock);
    while (table->offsets[index] != 0 && table->keys[index] != key) {
        index = (index + 1) % table->capacity;
    }

    Record* result = NULL;
    if (table->offsets[index] != 0) {
        result = table->records[index];
    }

    pthread_mutex_unlock(&table->lock);
    return result;
}
```
']

['Here is a basic C implementation of your task using file I/O operations, command line arguments parsing, and error handling. 

```c
#include <stdio.h>
#include <string.h>
#include <errno.h>

#define COMMENT_CHAR '#'

void printUsage() {
    printf("Usage: program [-n num] [file...]\n");
}

int countLines(FILE* file, int maxLines) {
    char line[256];  // Assuming the maximum length of a line is 255 characters.
    int lines = 0;

    while (fgets(line, sizeof(line), file)) {
        if (*line == COMMENT_CHAR) continue;  // Skipping comment lines.
        ++lines;
        if (maxLines > 0 && lines >= maxLines) break;  // Reading up to maxLines from each file.
    }

    return lines;
}

int main(int argc, char* argv[]) {
    int num = 0;
    int i = 1;
    if (argc > 1 && strcmp(argv[i], "-n") == 0) {  // Parsing command line arguments.
        if (sscanf(argv[++i], "%d", &num) != 1 || num < 0) {
            printUsage();
            return 1;
        }
        ++i;
    }

    if (argc == i) {  // Printing usage information if no input files are provided.
        printUsage();
        return 1;
    }

    int totalLines = 0;
    for (; i < argc; ++i) {
        FILE* file = strcmp(argv[i], "-") == 0 ? stdin : fopen(argv[i], "r");  // Opening files.
        if (!file) {
            perror("Error opening file");
            continue;
        }

        int lines = countLines(file, num);
        printf("%s: %d\n", argv[i], lines);
        totalLines += lines;

        if (file != stdin) fclose(file);  // Closing files.
    }

    printf("Total: %d\n", totalLines);
    return 0;
}
```
This program first parses command line arguments, checks for usage errors and then handles the file input accordingly. It counts lines from each valid file while skipping comment lines (i.e., starting with '#') up to a specified limit. In case of any error in opening or reading files, it prints an appropriate error message and continues to process other files. The program also supports reading from standard input if `-` is provided as an argument or when no file arguments are provided.
']

