['Here's a basic example of how you can approach it using C and some standard libraries including `sys/socket.h` for DNS resolution, `stdio.h` for file operations, `string.h` for string manipulation, and `netinet/in.h` for handling IP addresses.

Please note that this is a basic example and you will need to add more error checking and handle edge cases as per your needs. Also it does not include external logging system integration, but the code structure is there for future enhancements.

```c
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int resolve_dns(const char *hostname, u_char* ip) {
    struct hostent *he = gethostbyname(hostname);

    if (he == NULL) {
        herror("gethostbyname");
        return -1;
    }

    struct in_addr **addr_list = (struct in_addr **) he->h_addr_list;

    for(int i = 0; addr_list[i] != NULL; i++) {
        strcpy(ip, inet_ntoa(*addr_list[i]) );
        return 0;
    }

    return -1;
}

void process_csv(const char* filename){
    FILE *fp = fopen(filename,"r");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *field = strtok(line, ",");
        int i = 0;
        double avg = 0.0;
        double sum = 0.0;
        u_char ip[16]; // Assuming IPv4 address

        while (field != NULL) {
            if (i >= 2)
                sum += atof(field);

            field = strtok(NULL, ",");
            i++;
        }

        avg = sum / (i - 2); // Average of the last two fields

        resolve_dns(line, ip); // Resolving DNS

        printf("%s, %f\n", ip, avg); // Printing in CSV format
    }

    fclose(fp);
}

int main(){
    const char* filename = "sample.csv"; 
    process_csv(filename); 

    return 0; 
}
```
This program reads a csv file line by line, for each line it resolves DNS and computes average of last two fields. The result is then printed in CSV format along with the resolved IP address.

Please note that this code doesn't cover all edge cases as you may require them to be handled differently based on your specific requirements like error handling during file operations, line parsing, memory management etc. It also doesn't integrate an external logging system as it's not clear from the question how exactly it should be integrated.
']

