```python
import re
import subprocess

def fetch_from_api(server_name):
    # This is a placeholder for the API call, you need to implement this based on your requirements
    pass

def validate_inputs(data):
    required_fields = ['server_name', 'port', 'document_root']

    for field in required_fields:
        if not data.get(field):
            print(f"Missing required field: {field}")
            return False

    return True

def modify_config_file(data, server_type='apache', template_path='/etc/httpd/conf/httpd.conf'):

    if not validate_inputs(data):
        print("Invalid inputs")
        return False

    # Fetch additional settings from external data source
    data = {**fetch_from_api(data['server_name']), **data} 

    # Generate sed commands based on server type
    if server_type.lower() == 'apache':
        commands = [f"sed -i 's/ServerName .*/ServerName {data.get('server_name', '')}/' {template_path}",
                    f"sed -i 's/Port .*/Port {data.get('port', '')}/' {template_path}",
                    f"sed -i 's|DocumentRoot .*|DocumentRoot \"{data.get('document_root', '')}\"|' {template_path}"
                    ]
    elif server_type.lower() == 'nginx':
        commands = [f"sed -i 's/server_name .*/server_name {data.get('server_name', '')}/' {template_path}",
                    f"sed -i 's/listen .*;/listen {data.get('port', '')};/' {template_path}",
                    f"sed -i 's|root .*;|root \"{data.get('document_root', '')}\";|' {template_path}"
                    ]
    else:
        print("Unsupported server type")
        return False

    # Execute sed commands to modify configuration file
    for command in commands:
        subprocess.run(command, shell=True, check=True)

    return True
```
