```java
public class Pokemon {
    private String name;
    private String type;

    public Pokemon(String name, String type) {
        this.name = name;
        this.type = type;
    }

    public String getName() {
        return name;
    }

    public String getType() {
        return type;
    }
}

public class WeaknessResolver {
    public static String resolveWeaknesses(Pokemon pokemon) {
        // Assume library functions for retrieving type and name
        String typeName = getTypeFromLibrary(pokemon);
        String name = getNameFromLibrary(pokemon);

        if (typeName == null || name == null) {
            typeName = "Unknown";
            name = "Unknown";
        }

        switch (typeName) {
            case "Fire":
                return "Weakness: Water, Grass";
            case "Water":
                return "Weakness: Electric, Grass";
            case "Grass":
                return "Weakness: Fire, Ice";
            case "Electric":
                return "Weakness: Ground";
            default:
                return "No specific weakness found.";
        }
    }

    private static String getTypeFromLibrary(Pokemon pokemon) {
        // Simulated library call that might fail
        if (Math.random() > 0.5) {
            return null;
        }
