Write a function in C that manages a semaphore for a distributed logging system. The function should handle multiple semaphore operations, including incrementing and decrementing the semaphore's value, and ensure thread safety. The initial value of the semaphore should be configurable based on the expected number of concurrent log entries.

The function must also handle the following real-world constraints:
1. **External Data Source**: The initial value of the semaphore is provided by an external configuration file.
2. **System Dependencies**: The function must use `sem_open` and `sem_close` for semaphore operations and `pthread_mutex_lock` and `pthread_mutex_unlock` for thread synchronization.
3. **Performance Constraints**: Ensure that the function can handle high concurrency levels without significant performance degradation.
4. **Integration Issues**: The function should integrate seamlessly with an existing logging framework, which uses a custom error handling mechanism.

Developers must make trade-offs between efficiency, usability, maintainability, and scalability when implementing the solution.

```c
#include <semaphore.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    sem_t* sem;
    pthread_mutex_t mutex;
} SemaphoreManager;

SemaphoreManager* create_semaphore(const char* config_file) {
    SemaphoreManager* manager = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    if (manager == NULL) {
        return NULL;
    }

    int init_value = read_initial_value_from_config(config_file);
    if (init_value == -1) {
        free(manager);
        return NULL;
    }

    manager->sem = sem_open("my_semaphore", O_CREAT, 0644, init_value);
    if (manager->sem == SEM_FAILED) {
        free(manager);
        return NULL;
    }

    if (pthread_mutex_init(&manager->mutex, NULL) != 0) {
        sem_close(manager->sem);
        free(manager);
        return NULL;
    }

    return manager;
}

void destroy_semaphore(SemaphoreManager* manager) {
    pthread_mutex_destroy(&manager->mutex);
    sem_close(manager->sem);
    free(manager);
}

void acquire_semaphore(SemaphoreManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    sem_wait(manager->sem);
    pthread_mutex_unlock(&manager->mutex);
}

void release_semaphore(SemaphoreManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    sem_post(manager->sem);
    pthread_mutex_unlock(&manager->mutex);
}

