public class DatabaseProcessor
{
    public int ProcessObjects<T>(List<T> objects, IDbConnection connection, string sqlCommand)
    {
        var count = 0;

        try
        {
            connection.Open();

            foreach (var obj in objects)
            {
                var command = new MySqlCommand(sqlCommand, (MySqlConnection)connection);

                // Assuming all properties are columns in database. 
                foreach (var prop in typeof(T).GetProperties())
                {
                    command.Parameters.AddWithValue("@" + prop.Name, prop.GetValue(obj));
                }

                count += command.ExecuteNonQuery();
            }
        }
        catch (Exception ex)
        {
            // Log exception
            Console.WriteLine(ex);
        }
        finally
        {
            connection.Close();
        }

        return count;
    }
}
