```js
const axios = require('axios');
const fs = require('fs');
const https = require('https');

class OAuthDataCollector {
    constructor(repositoryBaseURL, repositoryAccessToken) {
        this.baseURL = repositoryBaseURL;
        this.accessToken = repositoryAccessToken;
        this.paused = false;
        this.dataArray = [];
    }

    async fetchAndCombineKeyCertificate(keyUrl, certUrl) {
        try {
            const keyResponse = await axios({
                method: 'get',
                url: `${this.baseURL}/${keyUrl}`,
                headers: { Authorization: `Bearer ${this.accessToken}` }
            });
            const certResponse = await axios({
                method: 'get',
                url: `${this.baseURL}/${certUrl}`,
                headers: { Authorization: `Bearer ${this.accessToken}` }
            });

            return [keyResponse.data, certResponse.data].join('\n');
        } catch (error) {
            console.log(`Error fetching key or certificate from repository: ${error}`);
            return '';
        }
    }

    async processOAuthRequestStream() {
        // This could be an infinite stream. 
        const requestStream = https.get('https://example.com/stream', response => {
            let data = '';

            response.on('data', (chunk) => {
                if (!this.paused) {
                    this.dataArray.push(JSON.parse(chunk));

                    // Considering keyUrl and certUrl are part of chunk's data
                    const pemData = await this.fetchAndCombineKeyCertificate(chunk.keyUrl, chunk.certUrl);
                    fs.writeFileSync('combined.pem', pemData);
                }
            });
        });

        requestStream.on('error', (error) => {
            console.log(`Error processing OAuth stream: ${error}`);
        });
    }

    pause() {
        this.paused = true;
    }

    resume() {
        this.paused = false;
    }
}
