["Here's an example of how this could be implemented in C. This code includes a simple sensor struct and some basic filtering logic to remove invalid readings based on age, number of readings in past 10 seconds, deviation from mean etc. Note that it doesn't include actual database interactions or scaling to additional sensors. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Sensor {
    int id;
    double reading;
    time_t timestamp;
} Sensor;

Sensor* createSensor(int id, double reading) {
    Sensor *s = malloc(sizeof(Sensor));
    s->id = id;
    s->reading = reading;
    s->timestamp = time(NULL);
    return s;
}

double getDeviationFromMean(Sensor* sensors, int length) {
    double sum = 0.0;
    for (int i = 0; i < length; i++) {
        sum += sensors[i].reading;
    }
    double mean = sum / length;

    // Calculate standard deviation
    double sumDeviationSquared = 0.0;
    for (int i = 0; i < length; i++) {
        sumDeviationSquared += pow(sensors[i].reading - mean, 2);
    }

    return sqrt(sumDeviationSquared / length);
}

// Simple filtering logic
int filterReading(Sensor* s, Sensor* sensorArray, int arrayLength) {
    double deviation = getDeviationFromMean(sensorArray, arrayLength);

    // Check age of reading
    if (difftime(time(NULL), s->timestamp) > 60.0) return 1;

    // Check number of readings in last 10 seconds
    int count = 0;
    for (int i = 0; i < arrayLength; i++) {
        if (difftime(time(NULL), sensorArray[i].timestamp) <= 10.0) count++;
        if (count > 5) return 1; // arbitrary threshold, modify according to use case
    }

    // Check deviation from mean
    if (s->reading > mean + 3*deviation || s->reading < mean - 3*deviation) return 1;

    return 0;
}
```
Please note that this is a simplistic example and does not consider all necessary factors, such as thread safety, performance optimization, database integration etc. In a real-world scenario, you would likely need to use more robust data structures, consider concurrency issues when accessing shared resources, optimize database interactions for speed, and implement proper error handling.
