['Here's a simple implementation in C using libtiff library for parsing TIFF images and openssl for hashing image data:

```c
#include <stdio.h>
#include <string.h>
#include <openssl/md5.h>
#include <tiffio.h>

typedef struct {
    uint16 bps;
    uint16 spp;
    uint32 extra_samples;
    unsigned char md5[MD5_DIGEST_LENGTH];
} TiffInfo;

TiffInfo getImageData(const char* filename) {
    TiffInfo info = {0};
    TIFF* tif = TIFFOpen(filename, "r");

    if (tif == NULL) {
        fprintf(stderr, "Cannot open file\n");
        return info;
    }

    // Parse image metadata
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &info.bps);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &info.spp);
    if (TIFFIsTiled(tif)) {
        uint32 extra;
        if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extra) == 1 && extra > 0) {
            info.extra_samples = extra;
        }
    }

    // Check if bps is supported
    switch (info.bps) {
        case 1:
        case 2:
        case 4:
        case 8:
        case 16:
            break;
        default:
            fprintf(stderr, "Unsupported bits per sample\n");
            return info;
    }

    // Calculate MD5 hash of image data
    MD5_CTX c;
    MD5_Init(&c);

    unsigned int width = TIFFScanlineSize(tif) / sizeof(uint32);
    uint32* buf = _TIFFmalloc(width * sizeof (uint32));

    for (uint32 row = 0; row < info.spp; row++) {
        TIFFReadScanline(tif, buf, row);
        MD5_Update(&c, buf, width * sizeof (uint32));
    }

    _TIFFfree(buf);
    MD5_Final((unsigned char*)&info.md5, &c);

    TIFFClose(tif);
    return info;
}
```

This code parses the TIFF file and extracts metadata using libtiff library. It then calculates an md5 hash of the image data using openssl's MD5 function, which is known to be secure but relatively slow. It verifies that the bits per sample value is supported (1, 2, 4, 8, or 16).

One potential improvement could be to use a faster cryptographic hash function for calculating the md5 hash if performance is a concern. Note also that there is not concurrency control in this code as it assumes you will call this function from a single thread. Adding locking mechanisms or using thread-safe data structures would be required if multiple threads can access this method simultaneously.
']

