    private readonly ILogger<SiteManager> _logger;

    public SiteManager(ILogger<SiteManager> logger)
    {
        _logger = logger;
    }

    public void AddSite(string directoryPath, string siteName)
    {
        if (!IsDirectoryWritable(directoryPath))
        {
            _logger.LogError("The provided directory is not writable.");
            return;
        }

        var webConfigFile = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigFile))
