            _logger.LogError("No web.config file found in the provided directory.");
            return;
        }

        try
        {
            var process = Process.Start(directoryPath, siteName);

            // Make sure to handle any started processes properly when function exits
            process?.WaitForExit();
            process?.Close();
        }
        catch (Exception e)
