['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <json-c/json.h>

#define EXPIRY_BUFFER 60 // seconds

int verifyAccessToken(const char *token) {
    CURL *curl;
    CURLcode res;
    struct json_object* parsed_json;

    curl = curl_easy_init();
    if(!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return 0;
    }

    char url[256];
    sprintf(url, "https://example.com/oauth/tokeninfo?access_token=%s", token);

    curl_easy_setopt(curl, CURLOPT_URL, url);
    /* if redirected, tell libcurl to follow redirection */
    curl_easy_setopt(curl, CURPT_FOLLOWLOCATION, 1L);
    res = curl_easy_perform(curl);

    /* Check for errors */
    if(res != CURLE_OK) {
        fprintf(stderr, "Failed to fetch OAuth2 token info: %s\n", curl_easy_strerror(res));
        return 0;
    }

    /* Parse the JSON response */
    parsed_json = json_tokener_parse(curl);
    if(!parsed_json) {
        fprintf(stderr, "Failed to parse OAuth2 token info\n");
        return 0;
    }

    /* Verify the JSON object against the schema */
    struct json_object* expires_in_obj = NULL;
    if (!json_object_object_get_ex(parsed_json, "expires_in", &expires_in_obj)) {
        fprintf(stderr, "Invalid JSON: missing 'expires_in' field\n");
        return 0;
    }

    int expires_in = json_object_get_int(expires_in_obj);
    if (expires_in < 1) {
        fprintf(stderr, "Invalid JSON: 'expires_in' field must be a positive integer\n");
        return 0;
    }

    time_t now = time(NULL);
    if (now > expires_in - EXPIRY_BUFFER) {
        fprintf(stderr, "Access token has expired\n");
        return 0;
    }

    /* Validate the JSON object */
    // TODO: Add more checks here to fully validate the JSON object against the OAuth2 access token schema.

    json_object_put(parsed_json);
    curl_easy_cleanup(curl);

    return 1;
}
```
Please install `libcurl-dev` and `json-c-devel` if you don't have them installed. The code above is a basic demonstration of how to use libcurl in C for fetching JSON data from an API, parses it with json-c, and verifies its fields. It does not include the full OAuth2 schema validation but gives a starting point. 

This function doesn't handle network errors like connection timeouts or server unavailability due to simplicity reasons. In production code you should add appropriate error handling for these situations. Additionally, it doesn't check if the access_token is in the 'Bearer' format since this requires checking a string pattern which is more complex and outside the scope of this example. 

Please note that C does not natively support JSON parsing. For this reason you would need to include an external library such as `json-c` or `jansson`, etc. You'll also need `libcurl` to fetch the token info from your server for full validation.
