function recursiveTraverseDOM(node, testFunc, selector) {
    const result = [];

    if (node && node.querySelectorAll) {
        for (let child of node.children) {
            if (testFunc(child, selector)) {
                result.push(child);
            }

            result.push(...recursiveTraverseDOM(child, testFunc, selector));
        }
    }

    return result;
}

function testElementClassOrId(element, selector) {
    if (selector[0] === '.') { // Class
        return element.classList.contains(selector.substring(1));
    } else if (selector[0] === '#') { // ID
        return element.id === selector.substring(1);
    }

    return false;
}
