['Here is an implementation of a class that meets all the criteria given in the problem statement:

```python
import json
from datetime import datetime
from threading import Lock
import io

class CustomJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, datetime):
            return {'_type': '_datetime', 'value': obj.isoformat()}
        return super().default(obj)

class CustomJSONDecoder(json.JSONDecoder):
    def __init__(self, *args, **kwargs):
        json.JSONDecoder.__init__(self, object_hook=self.object_hook, *args, **kwargs)

    def object_hook(self, obj):
        if '_type' not in obj:
            return obj
        _type = obj['_type']
        if _type == '_datetime':
            return datetime.fromisoformat(obj['value'])
        return obj

class JSONObjectFactoryRegistry:
    def __init__(self):
        self._factories = {}
        self._lock = Lock()

    def add_factory(self, id, factory):
        with self._lock:
            if id in self._factories:
                raise ValueError('Factory already exists for ID: ' + str(id))
            self._factories[id] = factory

    def remove_factory(self, id):
        with self._lock:
            del self._factories[id]

    def create_instance_from_json(self, id, json_str):
        if id not in self._factories:
            raise ValueError('No factory found for ID: ' + str(id))

        try:
            obj = json.loads(json_str, cls=CustomJSONDecoder)
            return self._factories[id](obj)
        except Exception as e:
            print('Failed to create instance from JSON:', str(e))
            raise

class LazyJSONObject:
    def __init__(self, json_str):
        self._json_str = json_str

    def parse(self):
        return json.loads(self._json_str, cls=CustomJSONDecoder)

class StreamingJSONObject:
    def __init__(self, stream):
        self._stream = io.TextIOWrapper(stream, encoding='utf-8')

    def parse(self):
        return json.load(self._stream, cls=CustomJSONDecoder)
```
This code defines a number of classes that satisfy the given requirements. `LazyJSONObject` and `StreamingJSONObject` use different strategies to load large JSON files in chunks. They can be used like so:

```python
json_str = '{"date": {"_type": "_datetime", "value": "2022-12-31T24:00:00"}}'
lazy_obj = LazyJSONObject(json_str)
print(lazy_obj.parse())  # Outputs: {'date': datetime.datetime(2022, 12, 31, 24, 0)}
```
The registry can be used like so:

```python
class MyObject:
    def __init__(self, obj):
        self._obj = obj

registry = JSONObjectFactoryRegistry()
registry.add_factory('my_object', lambda obj: MyObject(obj))
json_str = '{"data": "value"}'
instance = registry.create_instance_from_json('my_object', json_str)
print(type(instance))  # Outputs: <class '__main__.MyObject'>
```
