["Below is a C implementation with necessary data structures for managing dynamic allocation and initialization of memory for a system's database storage. It utilizes the concept of custom allocators to efficiently manage blocks of memory. However, it does not support concurrency due to its complexity, but it can be extended for thread-safe use. For simplicity and clarity, some aspects such as error handling and unit tests are omitted in this example:

```c
#include <stdlib.h>
#include <assert.h>
#include <string.h>

typedef struct Record {
    int value;
} Record;

// Structure to hold the block of memory
typedef struct Block {
    size_t size;
    void* data;
    struct Block* next;
} Block;

// Global variables for allocator
Block* allocatorHead = NULL;
size_t allocatedSize = 0;

void* customAlloc(size_t size) {
    assert(size > 0);

    // Allocate new block if necessary
    if (allocatedSize < size || allocatorHead == NULL) {
        Block* newBlock = malloc(sizeof(Block));
        assert(newBlock != NULL);
        newBlock->data = malloc(size);
        assert(newBlock->data != NULL);
        newBlock->next = allocatorHead;
        newBlock->size = size;
        allocatorHead = newBlock;
    }

    // Allocate memory from existing block
    void* allocatedMemory = allocatorHead->data;
    allocatorHead->data += size;
    allocatorHead->size -= size;
    allocatedSize -= size;

    return allocatedMemory;
}

void customFree(Block* block) {
    assert(block != NULL);

    Block** prev = &allocatorHead;
    while (*prev != block && *prev != NULL) {
        prev = &((*prev)->next);
    }
    assert(*prev != NULL);  // Assert that the block is part of our allocator

    if ((*prev)->size == 0) {  // If this block is completely free
        Block* nextBlock = *prev;
        *prev = (*prev)->next;  // Remove this block from list
        free(nextBlock->data);  // Free its data
        free(nextBlock);  // And finally, free the block itself
    }
}

Record* initializeDatabaseStorage(size_t numRecords) {
    Record* records = customAlloc(numRecords * sizeof(Record));

    // Initialize records
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].value = 0;  // Or any other initial value
    }

    return records;
}

void deinitializeDatabaseStorage(Record* records, size_t numRecords) {
    customFree((Block*) (records - sizeof(Block)));  // Free the block of memory allocated for the records
}
```
Please note that this is a simplified version. For an actual system, you need to have error handling and unit tests as well, and handle concurrency carefully with appropriate synchronization mechanisms like mutexes or lock-free data structures if possible. Also, compacting can be handled by periodically rehashing the hash table which can be done separately.
"]

