    jmethodID inetSocketAddressConstructor = (*env)->GetMethodID(env, inetSocketAddressClass, "<init>", "(Ljava/lang/String;I)V"); 

    jobject socketAddressObj = (*env)->NewObject(env, inetSocketAddressClass, inetSocketAddressConstructor, (*env)->NewStringUTF(env, remote_addr), port_number); 
    jboolean result = (*env)->CallBooleanMethod(env, channelObj, connectMethod, socketAddressObj); 

    // Handle connection state changes...

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}
