['```c
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>
#include <time.h>
#define TABLE_SIZE 10007

typedef struct {
    int key;
    double value;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

Node** hashTable;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int hashingFunction(int key) {
    return key % TABLE_SIZE;
}

Record createRandomRecord() {
    Record record;
    record.key = rand();
    record.value = (double)(rand()) / RAND_MAX;
    return record;
}

void initHashTable(int size) {
    srand(time(NULL));
    hashTable = malloc(sizeof(Node*) * size);
    assert(hashTable != NULL);
    for (int i = 0; i < size; ++i) {
        hashTable[i] = NULL;
    }
}

void insertRecord(Record record) {
    int hashIndex = hashingFunction(record.key);
    Node* newNode = malloc(sizeof(Node));
    assert(newNode != NULL);
    newNode->record = record;
    pthread_mutex_lock(&lock);
    newNode->next = hashTable[hashIndex];
    hashTable[hashIndex] = newNode;
    pthread_mutex_unlock(&lock);
}

Record* searchRecord(int key) {
    int hashIndex = hashingFunction(key);
    Node* node = hashTable[hashIndex];
    while (node != NULL && node->record.key != key) {
        node = node->next;
    }
    if (node == NULL) return NULL;
    else return &(node->record);
}
```
