// A hash table to store records with keys and values.
static Record* hashTable[SIZE] = {NULL}; 

void initializeArrays(int min, int max) {
    assert(max > min); // make sure the range is valid

    for (int i = 0; i < SIZE; ++i) {
        Record *record = malloc(sizeof(Record));

        if (!record) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        record->key = rand() % (max - min + 1) + min; // set a random key within the range
        pthread_mutex_lock(&lock); // lock before inserting into hash table to prevent other threads from accessing
        hashTable[record->key] = record; 
        pthread_mutex_unlock(&lock); // unlock after insertion
    }
}
