['```c
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <Magick++.h>

int convertImage(const char* inputFilePath, const char* outputDir, const char** supportedFormats) {
    struct stat buffer;

    // Check if the file exists
    if (stat(inputFilePath, &buffer) != 0) {
        fprintf(stderr, "Input file does not exist.\n");
        return 1;
    }

    Magick::Image image;
    try {
        // Read the input image
        image.read(inputFilePath);
    } catch (Magick::Exception &error_) {
        fprintf(stderr, "Caught exception: %s\n", error_.what());
        return 1;
    }

    const char* outputFormat = NULL;
    int i = 0;
    while (supportedFormats[i]) {
        if (!strcasecmp(image.format().data(), supportedFormats[i])) {
            outputFormat = supportedFormats[i];
            break;
        }
        ++i;
    }

    // If the image format is not supported, return error
    if (outputFormat == NULL) {
        fprintf(stderr, "Input file format not supported.\n");
        return 1;
    }

    try {
        char* outputFilePath = malloc((strlen(inputFilePath) + strlen(outputDir) + 20)*sizeof(char));
        sprintf(outputFilePath, "%s/%s.%s", outputDir, "converted_image", supportedFormats[i]);

        // Write the image to the new format in the specified directory
        image.write(outputFilePath);

        free(outputFilePath);
    } catch (Magick::Exception &error_) {
        fprintf(stderr, "Caught exception: %s\n", error_.what());
        return 1;
    }

    return 0;
}
```
