['Here is your C code block for running a command in background using fork and wait system call:
```c
#include <sys/types.h>
#include <unistd.h>
#include <stdlib.h>
#include <sys/wait.h>
#include <errno.h>
#include <string.h>

int run_command(const char *cmd) {
    pid_t pid = fork();

    if (pid == -1) { // error occurred
        fprintf(stderr, "fork: %s\n", strerror(errno));
        return 0;
    } else if (pid == 0) { // child process
        execl("/bin/sh", "sh", "-c", cmd, NULL);
        fprintf(stderr, "execl: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    } else { // parent process
        int status;
        if (waitpid(pid, &status, 0) == -1) {
            fprintf(stderr, "waitpid: %s\n", strerror(errno));
            return 0;
        }

        if (!WIFEXITED(status)) { // process was not terminated normally
            fprintf(stderr, "process was not terminated normally\n");
            return 0;
        }

        int exit_code = WEXITSTATUS(status);
        if (exit_code != EXIT_SUCCESS) { // process exited with non-zero status code
            fprintf(stderr, "process exited with non-zero status code: %d\n", exit_code);
            return 0;
        }
    }

    return 1;
}
```
