import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.charset.StandardCharsets;

public class Main {
    public static String md5Hash(String message) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashInBytes = md.digest(message.getBytes(StandardCharsets.UTF_8));

            StringBuilder sb = new StringBuilder();
            for (byte b : hashInBytes) {
                sb.append(String.format("%02x", b));
            }

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            System.err.println("No MD5 algorithm available: " + e.getMessage());
        }

        return null; // or throw a custom exception
    }

    public static void main(String[] args) {
        String message = "Hello, world!";
        System.out.println(md5Hash(message));
    }
}
```
For performance considerations: The MD5 algorithm is not designed for hashing passwords or sensitive data and its security level has been compromised since 2010. It's recommended to use a stronger hash function such as SHA-256, but please note that they're also less efficient than MD5. In case of performance issues you may consider storing the computed hash on disk or using memoization if your application allows it.
