    if(file == NULL){
        fprintf(stderr, "Could not open %s for reading\n", fileName);
        return NULL;
    }

    char* line = NULL;
    size_t len = 0;

    while (getline(&line, &len, file) != -1){
      processLine(line);
    }

    fclose(file);
    if(line) free(line);  // Free allocated memory

    return NULL;
}

int main() {
    /* Initial setup for logging */
    logFile = fopen("log.txt", "w");
    if(!logFile){
        fprintf(stderr, "Could not open log file for writing\n");
        return 1;
    }

    char* configDirName = configurationManager_updateDefaultTheme(default_theme); // get updated theme

    /* Read multiple files concurrently */
    pthread_t threads[3];
    char* fileNames[] = {"file1.txt", "file2.txt", "file3.txt"};

    for (int i = 0; i < 3; ++i) {
        if(pthread_create(&threads[i], NULL, processFile, fileNames[i])){
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    /* Wait for all threads to finish */
    for (int i = 0; i < 3; ++i) {
        if(pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            return 1;
        }
    }

    /* Close logging */
    fclose(logFile);

    return 0;
}
```
This program reads text files concurrently using multiple threads and processes each line as it is read. It logs relevant information to a file, which is opened in the main function and closed before returning from main. The processLine function shows how you could dynamically allocate memory for each line and free it after use.

