import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class HashUtil {
    private static final MessageDigest digest;

    static {
        try {
            digest = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public synchronized byte[] generateHash(String input) {
        return digest.digest(input.getBytes(StandardCharsets.UTF_8));
    }
}
```

2. Caching mechanism with a maximum size limit:

```java
import java.util.LinkedHashMap;
import java.util.Map;

public class HashCache {
    private final Map<String, byte[]> cache = new LinkedHashMap<>() {
        @Override
        protected boolean removeEldestEntry(Map.Entry eldest) {
            return size() > Constants.MAX_CACHE_SIZE;
        }
    };

    public synchronized byte[] getOrComputeHash(String input, HashUtil hashUtil) {
        if (cache.containsKey(input)) {
            return cache.get(input);
        } else {
            byte[] hash = hashUtil.generateHash(input);
            cache.put(input, hash);
            return hash;
        }
    }
}
```

