    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    Record** table;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* hash_table = malloc(sizeof(HashTable));
    if (hash_table == NULL) {
        return NULL;
    }

    hash_table->count = 0;
    hash_table->capacity = initial_capacity;
    hash_table->table = calloc(initial_capacity, sizeof(Record*));
    if (hash_table->table == NULL) {
        free(hash_table);
        return NULL;
    }

    pthread_mutex_init(&hash_table->lock, NULL);
    return hash_table;
}

void delete_record(HashTable* hash_table, int key) {
    pthread_mutex_lock(&hash_table->lock);

    size_t index = key % hash_table->capacity;
    while (hash_table->table[index] != NULL && hash_table->table[index]->key != key) {
        index = (index + 1) % hash_table->capacity;
    }

    if (hash_table->table[index] != NULL) {
        free(hash_table->table[index]);
        hash_table->table[index] = NULL;
        hash_table->count--;
    }

    pthread_mutex_unlock(&hash_table->lock);
}

int insert_record(HashTable* hash_table, int key, double value) {
    if (hash_table->count >= hash_table->capacity / 2) {
        return -1; // Table is too full, not enough space to resize.
    }

    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        return -2; // Out of memory.
    }

    record->key = key;
    record->value = value;

    pthread_mutex_lock(&hash_table->lock);

    size_t index = key % hash_table->capacity;
    while (hash_table->table[index] != NULL) {
        if (hash_table->table[index]->key == key) {
            free(record); // Duplicate key, not inserted.
            return -3; 
        }

        index = (index + 1) % hash_table->capacity;
    }

    hash_table->table[index] = record;
    hash_table->count++;

    pthread_mutex_unlock(&hash_table->lock);
    return 0; // Success.
}

Record* find_record(HashTable* hash_table, int key) {
    pthread_mutex_lock(&hash_table->lock);

    size_t index = key % hash_table->capacity;
    while (hash_table->table[index] != NULL && hash_table->table[index]->key != key) {
        index = (index + 1) % hash_table->capacity;
    }

    Record* result = hash_table->table[index];
    pthread_mutex_unlock(&hash_table->lock);
    return result;
}
