```c
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>

typedef struct Record {
    int value;
} Record;

// Hash table node
typedef struct Node {
    int key;
    Record* record;
    struct Node* next;
} Node;

// Global hash table and mutex for thread safety
#define TABLE_SIZE 269 // Prime number to reduce collisions
Node** hashTable;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initHashTable() {
    hashTable = calloc(TABLE_SIZE, sizeof(Node*));
    assert(hashTable != NULL); // Check if memory allocation was successful. If not, terminate the program with an error message.
}

// Hash function (simple modulo)
int hash(int key) {
    return key % TABLE_SIZE;
}

void insertRecord(int key, Record* record) {
    pthread_mutex_lock(&lock); // Ensure thread safety for concurrent access.

    int index = hash(key);
    Node* node = malloc(sizeof(Node));
    assert(node != NULL); // Check if memory allocation was successful. If not, terminate the program with an error message.

    node->key = key;
    node->record = record;
    node->next = hashTable[index]; 
    hashTable[index] = node;

    pthread_mutex_unlock(&lock); // Release lock after operation is done.
}

Record* lookupRecord(int key) {
    int index = hash(key);
    Node* node = hashTable[index];

    while (node != NULL) {
        if (node->key == key) return node->record; // Record found.
        node = node->next;
    }

    return NULL; // Record not found.
}
```
