```c
bool isAvailable(const char* format) {
    // Load the library using dlopen()
    void *handle = dlopen("libraryname", RTLD_LAZY);

    if (handle == NULL) return false;

    // Check availability of necessary symbols
    void *symbol = dlsym(handle, format); 

    if (symbol == NULL) {
