    ImageFormat* availableFormats = NULL;

    // Loop over each format
    const char** formats = getSupportedFormats(); 
    for (const char** ptr = formats; *ptr != NULL; ++ptr) {
        if (isAvailable(*ptr)) {
            // If the format is available, dynamically load it and add it to the list
