// Implement a C function that takes a string and a size limit as input, and returns a new string with a slash appended to the end if the input string does not exceed the size limit.
public unsafe char* AppendSlash(char* str, int limit)
{
    if (str == NULL || *str == '\0') return NULL;

    var length = 0;
    while (*(str + length) != '\0') 
    {
        length++;

        // Return NULL if the input string exceeds the size limit.
        if (length >= limit) return NULL;
    }

    *(str + length) = '/';
    *(str + length + 1) = '\0';

    return str;
}
