function getElementsBySelectorRecursively(node, selector, testFunc) {
    var result = [];

    if (testFunc(node)) result.push(node);

    node = node.firstChild;
    while (node !== null) 
    {
        Array.prototype.push.apply(result, getElementsBySelectorRecursively(node, selector, testFunc));
        node = node.nextSibling;
    }

    return result;
}
