async function traverseDOMAsync(rootElement, selector, testFunction) {
  if (!(rootElement instanceof HTMLElement)) {
    throw new Error('Invalid root element');
  }

  let result = [];
  let stack = [...rootElement.children];

  while (stack.length > 0) {
    const node = stack.pop();

    if (testFunction(node, selector)) {
      result.push(node);
    }

    stack.push(...node.children);
  }

  return result;
}
