#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/time.h>
#include <errno.h>
#include <pthread.h>
#include <curl/curl.h>

struct RateLimit {
    pthread_mutex_t mutex;
    double interval;
    struct timeval lastAccess;
};

void setRateLimit(struct RateLimit *rateLimit, double interval) {
    rateLimit->interval = interval;
    gettimeofday(&(rateLimit->lastAccess), NULL);
}

int isWithinRateLimit(struct RateLimit *rateLimit) {
    struct timeval now;
    gettimeofday(&now, NULL);
    double elapsedTime = 
        (double)(now.tv_sec - rateLimit->lastAccess.tv_sec) + 
        (double)(now.tv_usec - rateLimit->lastAccess.tv_usec)/1000000;

    if (elapsedTime >= rateLimit->interval) {
        gettimeofday(&(rateLimit->lastAccess), NULL);
        return 1;
    }
    return 0;
}

size_t handleResponse(void *contents, size_t size, size_t nmemb, void *userp) {
    /* Handle API response here */
    return size * nmemb;
}

void sendDataToMonitoringSystem(const char *data) {
    CURL *curl = curl_easy_init();

    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://api.monitoringsystem.com");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);

        /* Define response handler */
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, handleResponse);

        /* Perform API call */
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error sending data to monitoring system: %s\n", 
                    curl_easy_strerror(res));
        }

        /* Always cleanup */
        curl_easy_cleanup(curl);
    }
}

int resolveDNS(const char *hostname, u_char ip[INET6_ADDRSTRLEN], struct RateLimit *rateLimit) {
    if (!isWithinRateLimit(rateLimit)) {
        return -1;  /* Exceeded rate limit */
    }

    struct hostent *host = gethostbyname(hostname);
    if (host == NULL) {
        fprintf(stderr, "Error resolving DNS for %s: %s\n", hostname, hstrerror(h_errno));
        return -1;
    }

    /* Assume only one IP is returned */
    struct in_addr **addrList = (struct in_addr **)host->h_addr_list;
    strncpy((char *)ip, inet_ntoa(*addrList[0]), INET6_ADDRSTRLEN);

    char data[256];
    snprintf(data, sizeof(data), "DNS resolution for %s: %s", hostname, ip);
    sendDataToMonitoringSystem(data);

    return 0;
}
```
