['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct data_record {
    long offset;
    int key;
    float data;
} data_record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file;

float random_range(int min, int max) {
    return (rand() / (float) RAND_MAX) * (max - min) + min;
}

void log_to_file(const char* msg) {
    pthread_mutex_lock(&lock);
    fprintf(log_file, "%s\n", msg);
    pthread_mutex_unlock(&lock);
}

data_record* initialize_database(const char *csv_filename, float min_val, float max_val) {
    data_record* db = NULL;
    FILE *file = fopen(csv_filename, "r");

    if (!file) {
        log_to_file("Failed to open CSV file");
        return NULL;
    }

    char buffer[1024];
    int record_count = 0;

    while (fgets(buffer, sizeof(buffer), file)) {
        long offset;
        int key;

        if (sscanf(buffer, "%ld,%d", &offset, &key) != 2) {
            log_to_file("Failed to parse CSV line");
            continue;
        }

        db = realloc(db, sizeof(*db) * (record_count + 1));
        db[record_count].offset = offset;
        db[record_count].key = key;
        db[record_count].data = random_range(min_val, max_val);

        log_to_file("Initialized record");
        record_count++;
    }

    fclose(file);
    return db;
}

int main() {
    srand(time(NULL));
    log_file = fopen("log.txt", "w");

    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    data_record* db = initialize_database("data.csv", 0.0f, 1.0f);

    if (!db) {
        fprintf(stderr, "Failed to initialize database\n");
        return -1;
    }

    fclose(log_file);
    free(db);
    return 0;
}
```
