#include <string.h>
#include <stdlib.h>

char* processString(const char *inputStr, size_t limit, int allowTruncation) {
    if (inputStr == NULL) return NULL; // handling null pointers

    size_t inputLength = strlen(inputStr);

    if (!allowTruncation && inputLength > limit) return NULL; 

    size_t newLen = inputLength <= limit ? inputLength + 2 : (limit % 2 == 0 ? limit / 2 - 1 : limit / 2) + 2; // calculating the new length of string with slash

    if (allowTruncation && newLen < inputLength + 2 ) return NULL; // checking for truncation

    char* outputStr = malloc(newLen); // allocating memory for output string

    if (outputStr == NULL) { 
        fprintf(stderr, "Memory allocation error"); 
        exit(EXIT_FAILURE); // checking for failure of dynamic memory allocation
    }

    strncpy(outputStr, inputStr, newLen - 2); // copying the input string to output string

    outputStr[newLen-2] = '/'; // appending slash to the end
    outputStr[newLen-1] = '\0'; // adding null character at the end of string

    return outputStr;
}
``` 
