// Helper function to find maximum in array
int maxInArray(int* array, size_t n){
    int max = INT_MIN;
    for (size_t i = 0; i < n; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

// Main function to read and process input
int main() {
    size_t capacity = 2; // Initial capacity for reallocating memory
    int* numbers = malloc(capacity * sizeof(int));

    if (numbers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    size_t n = 0; // Current number of elements in array
    char buffer[256]; // Buffer for reading input as string first

    while (fgets(buffer, sizeof(buffer), stdin) != NULL) {
        if (!validateInput(buffer)) {
            continue;
        }

        int value = atoi(buffer);

        // Check capacity and reallocate memory as needed
        if (n == capacity){
            capacity *= 2; 
            numbers = realloc(numbers, capacity * sizeof(int));

            if (numbers == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                return 1;
            }
        }

        // Add value to array
        numbers[n++] = value;
    }

    printf("The largest number is %d\n", maxInArray(numbers, n));

    free(numbers);
}
```
