```c
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>

typedef struct {
    const EVP_CIPHER *(*init)(void);
    void (*destroy)(EVP_CIPHER_CTX *ctx);
} cipher_ops;

cipher_t* create_cipher(const char* cipher_type) {
    cipher_ops ops;

    if (strcmp(cipher_type, "AES") == 0) {
        ops.init = EVP_aes_256_cbc;
        ops.destroy = EVP_CIPHER_CTX_free;
    } else if (strcmp(cipher_type, "DES") == 0) {
        ops.init = EVP_des_ede3_cbc;
        ops.destroy = EVP_CIPHER_CTX_free;
    } else if (strcmp(cipher_type, "RSA") == 0) {
        ops.init = EVP_RSA_3;
        ops.destroy = EVP_PKEY_free;
    } else {
        return NULL;  // Invalid cipher type
    }

    cipher_t* cipher = (cipher_t*)malloc(sizeof(cipher_t));
    if (cipher == NULL) {
        return NULL;  // Memory allocation failed
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        free(cipher);
        return NULL;  // Failed to initialize cipher context
    }

    const EVP_CIPHER* cipher = ops.init();
    if (cipher == NULL) {
        ops.destroy(ctx);
        free(cipher);
        return NULL;  // Failed to get the required cipher
    }

    cipher->ops = &ops;
    cipher->ctx = ctx;

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) {
        ops.destroy(ctx);
        free(cipher);
        return NULL;  // Failed to initialize encryption
    }

    return cipher;
}
```
