['Here is an outline of how you can implement a custom allocator in C with a logging function along with unit tests to test these functions. Please note that this is a complex task and may require more than just one function to fully implement. This answer also does not cover all the requirements, but it should serve as a good starting point for implementing your task.

For the logging functionality:
```C
#include <pthread.h>
#include <stdarg.h>
#include <string.h>

typedef enum {DEBUG, INFO, ERROR} log_level;
static pthread_key_t key;
static pthread_once_t key_once = PTHREAD_ONCE_INIT;

void make_log_buffer() {
    char* buf = malloc(4096);
    if (buf != NULL) {
        *buf = '\0';
        pthread_setspecific(key, buf);
    }
}

void logmsg(log_level level, const char* message, ...) {
    pthread_once(&key_once, make_log_buffer);
    char* bufptr;
    if ((bufptr = (char*)pthread_getspecific(key)) == NULL) {
        return;
    }

    va_list args;
    va_start(args, message);
    int len = vsnprintf(NULL, 0, message, args);
    if ((strlen(bufptr) + len + 24) < 4096) { // reserve some space for other stuff
        char timestamp[20];
        time_t now;
        time(&now);
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", localtime(&now));
        sprintf(bufptr+strlen(bufptr), "[%s][%s] ", timestamp, level == DEBUG ? "DEBUG" : (level == INFO ? "INFO" : "ERROR"));
        vsprintf(bufptr + strlen(bufptr), message, args);
    } else {
        // Handle buffer overflow here or whatever you want to do.
    }
}
```
For the custom allocator:
```C
#include <pthread.h>
#define HASH_TABLE_SIZE 1024
typedef struct Record {
    int value;
    size_t next;
} Record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static long offsets[HASH_TABLE_SIZE];
static Record records[1024*1024];
static size_t freeList = 0; // Index of the first free block in 'records'

void initAllocator() {
    memset(offsets, 0xFF, sizeof(offsets));
    for (size_t i=0; i<1024*1024-1; i++) {
        records[i].next = i+1;
    }
    records[1024*1024-1].next = 0xFFFFFFFF; // End of list marker.
}

void* allocate(int key, int value) {
    pthread_mutex_lock(&lock);
    size_t i = key % HASH_TABLE_SIZE;
    while (offsets[i] != 0xFFFFFFFF) { // Linear probing.
        if (records[offsets[i]].value == value) {
            pthread_mutex_unlock(&lock);
            return &records[offsets[i]];
        }
        i = (i + 1) % HASH_TABLE_SIZE; // Next slot in the hash table.
    }

    if (freeList != 0xFFFFFFFF) {
        size_t recordIndex = freeList;
        freeList = records[recordIndex].next;
        offsets[i] = recordIndex;
        records[recordIndex].value = value;
        pthread_mutex_unlock(&lock);
        return &records[recordIndex];
    } else {
        // Handle out of space here.
        pthread_mutex_unlock(&lock);
        return NULL;
    }
}
```
For the unit tests:
```C
