['Here is a sample implementation of the function `log_message` in C that meets your requirements. It uses the `fopen`, `vsnprintf` and `va_start/va_end` functions to log messages with different levels (debug, info, error) and includes a timestamp. 

```c
#include <stdio.h>
#include <stdarg.h>
#include <time.h>

void log_message(int level, const char *format, ...) {
    FILE *file = fopen("log.txt", "a");

    if (file == NULL) {
        printf("Failed to open the file.\n");
        return;
    }

    time_t rawtime;
    struct tm * timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    char timestamp[20];  // Assuming a timestamp string length of up to 20 characters.
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    const int MAX_MSG_LEN = 1024; // Assuming maximum message length of 1024 characters.
    char buffer[MAX_MSG_LEN];

    va_list args;
    va_start(args, format);
    vsnprintf(buffer, MAX_MSG_LEN, format, args);
    va_end(args);

    if (level == 1) {
        fprintf(file, "[DEBUG] %s - %s\n", timestamp, buffer);
    } else if (level == 2) {
        fprintf(file, "[INFO]  %s - %s\n", timestamp, buffer);
    } else if (level == 3) {
        fprintf(file, "[ERROR] %s - %s\n", timestamp, buffer);
    }

    fclose(file);
}
```

