```C
#include <openssl/evp.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    EVP_CIPHER *(*cipher)();
} ciphers;

ciphers ciphers[] = {
    {EVP_aes_128_ecb}, 
    {EVP_aes_256_cbc}, 
    {EVP_chacha20_poly1305},
};

void (*callback)(char *encrypted, size_t length) = NULL;

int encrypt(const char* plaintext, int plaintextLength, const unsigned char* key, EVP_CIPHER*(*cipher)(), char* encrypted){
    EVP_CIPHER_CTX *ctx;
    int len = 0;
    int ciphertext_len = 0;

    if(!(ctx = EVP_CIPHER_CTX_new())) 
        return -1;

    /* Initialize the encryption operation. IMPORTANT - ensure you have a key */
    if(1 != EVP_EncryptInit_ex(ctx, cipher(), NULL, key, NULL))
       return -1;

    /* Provide the message to be encrypted, and obtain the encrypted output. */
    if(1 != EVP_EncryptUpdate(ctx, (unsigned char*)encrypted, &len, (const unsigned char*)plaintext, plaintextLength))
        return -1;

    ciphertext_len = len;

    /* Finalize the encryption. Further ciphertext bytes may be written at this stage */
    if(1 != EVP_EncryptFinal_ex(ctx, (unsigned char*)encrypted + len, &len)) 
        return -1;

    ciphertext_len += len;

    /* Clean up */
    EVP_CIPHER_CTX_free(ctx);

    if(callback != NULL) {
        callback(encrypted, ciphertext_len);
    }

    return ciphertext_len;
}
```
In this example, `ciphers` is an array of structs containing a function pointer to each supported cipher. The `encrypt()` function takes as input the plaintext, its length, a key for encryption and a chosen cipher, and returns the encrypted text. If a callback function is set, it'll be called after encryption with the encrypted data and its length as parameters.

