pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void logMessage(const char* message, const char* level) {
    pthread_mutex_lock(&logMutex);
    // Add your own logging mechanism here (e.g., syslog, printf to file)
    printf("[%s] %s\n", level, message);
    pthread_mutex_unlock(&logMutex);
}

int establishConnectionAndAllocateResources(const char* socketPath, int offsetCount, 
                                          int keyCount, int recordCount, 
                                          int minValue, int maxValue) {
    // Verify input parameters
    if (offsetCount <= 0 || keyCount <= 0 || recordCount <= 0 || 
        minValue >= maxValue || strlen(socketPath) == 0) {
        logMessage("Invalid parameters", "ERROR");
        return -1;
    }

    // Allocate memory for offset and key arrays
    long* offsetArray = malloc(offsetCount * sizeof(*offsetArray));
    int* keyArray = calloc(keyCount, sizeof(*keyArray));
    if (offsetArray == NULL || keyArray == NULL) {
        logMessage("Memory allocation failed", "ERROR");
        free(offsetArray);
        free(keyArray);
        return -1;
    }

    // Allocate memory for record array
    record_t* recordArray = calloc(recordCount, sizeof(*recordArray));
    if (recordArray == NULL) {
        logMessage("Memory allocation failed", "ERROR");
        free(offsetArray);
        free(keyArray);
        return -1;
    }

    // Initialize record array with random values within given range
    srand(time(NULL));  // seed the rand() function for better randomness
    for (int i = 0; i < recordCount; ++i) {
        recordArray[i].value = minValue + rand() % ((maxValue + 1) - minValue);
    }

    // Establish connection to Unix domain socket
    int sockfd = socket(AF_UNIX, SOCK_STREAM, 0);
    if (sockfd < 0) {
        logMessage("Socket creation failed", "ERROR");
        free(offsetArray);
        free(keyArray);
        free(recordArray);
        return -1;
    }

