        pthread_mutex_lock(&lock);
        if(size >= capacity){
            capacity = (capacity == 0) ? 1 : capacity * 2;
            list = realloc(list, sizeof(*list) * capacity);
        }

        // Populate the new element.
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->RNTI = ueInfo.RNTI;
