    isRunning = 1;
    pthread_t threadId;
    int err = pthread_create(&threadId, NULL, &updateList, NULL); 

    if (err != 0) {
        printf("Failed to create thread :[%s]", strerror(err));
        isRunning = 0;
    }
}

void terminate() {
