['Here's a basic implementation of your requirements in C. The code is quite complex and extensive for this format, but it should give you an idea about how to implement the functionality. Note that proper error handling and resource management are not shown here due to space constraints. For a full-featured solution, consider using a robust framework or library:

```c
#include <semaphore.h>
#include <pthread.h>
#include <sys/time.h> // for timed wait functionality
#include <stdlib.h>  // for malloc
#include <string.h>  // for strlen, memset
#include <errno.h>   // for errno constants
#include <stdatomic.h> // for atomic operations

// Configurable settings
_Atomic(int) max_concurrent_threads;
sem_t *semaphore = NULL;
pthread_mutex_t mutex;

void logging(_Bool isError, const char* logMsg) {
    // Replace with your own logging mechanism here, e.g., syslog or a custom logger
}

int createSemaphore(int initialValue) {
    if ((semaphore = sem_open("/mySemaphore", O_CREAT | O_EXCL, 0644, initialValue)) == SEM_FAILED) {
        logging(1, "Error creating semaphore");
        return -1; // failed to create semaphore
    }

    if (pthread_mutex_init(&mutex, NULL) != 0) {
        logging(1, "Error initializing mutex");
        sem_close(semaphore);
        return -2; // failed to initialize mutex
    }

    max_concurrent_threads = ATOMIC_VAR_INIT(initialValue);
    return 0; // successful creation
}

void destroySemaphore() {
    sem_close(semaphore);
    pthread_mutex_destroy(&mutex);
    memset(&semaphore, '\0', sizeof(semaphore));
    max_concurrent_threads = ATOMIC_VAR_INIT(0); // reset the value
}

int acquireSemaphoreWithTimeout(unsigned int timeout) {
    struct timespec ts;

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        logging(1, "Error getting current time");
        return -1; // failed to get current time
    }

    ts.tv_sec += timeout;

    if (sem_timedwait(semaphore, &ts) != 0) {
        logging(1, "Timeout while waiting for semaphore");
        return -2; // timed out
    }

    if (atomic_fetch_sub(&max_concurrent_threads, 1) < 0) {
        atomic_fetch_add(&max_concurrent_threads, 1); // restore the value in case of error
        logging(1, "Too many concurrent threads");
        sem_post(semaphore);
        return -3; // too many concurrent threads
    }

    pthread_mutex_lock(&mutex);
    logging(0, "Semaphore acquired successfully");
    return 0; // successful acquisition
}

void releaseSemaphore() {
    atomic_fetch_add(&max_concurrent_threads, 1);
    sem_post(semaphore);
    pthread_mutex_unlock(&mutex);
    logging(0, "Semaphore released");
}
```

Please note that actual implementation might require more careful handling of concurrency and error cases. Also be aware that using semaphores for synchronization across processes or nodes may involve additional complexity depending on your specific requirements and constraints. 

For a robust solution, consider using existing libraries or frameworks that provide a wide range of features for managing semaphores and other resources in a thread-safe manner.
']

