#define MAX_NUM_OF_STRUCTURES 10000
NFAPI_CRC_INDICATION_PDU_T *nfapiPool[MAX_NUM_OF_STRUCTURES];
int numOfStructures = 0;
pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;
time_t lastUpdateTime;
int qosIndicatorCount[5] = {0, 0, 0, 0, 0};

NFAPI_CRC_INDICATION_PDU_T* createNFAPIPdu() {
    pthread_mutex_lock(&poolMutex);

    if (numOfStructures >= MAX_NUM_OF_STRUCTURES) {
        // Handle error here, e.g., by logging and returning NULL
        pthread_mutex_unlock(&poolMutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (pdu == NULL) {
        // Handle error here, e.g., by logging and returning NULL
        pthread_mutex_unlock(&poolMutex);
        return NULL;
    }

    srand(time(NULL));  // Seed the random number generator

    pdu->crcIndicationRel8Tag.CRCFLAG = rand() % 256;  // Randomly set CRCFLAG
    pdu->rxUeInformationTag.UEID = rand();  // Randomly set UEID
    pdu->rxUeInformationTag.RNTI = rand();  // Randomly set RNTI

    for (int i = 0; i < 5; ++i) {
        pdu->rxUeInformationTag.qosIndicator[i] = rand();  // Randomly set QoS Indicators
    }

    nfapiPool[numOfStructures++] = pdu;

    time(&lastUpdateTime);  // Update last update time
    qosIndicatorCount[(time(NULL) / 5) % 5] += 1;  // Increment QoS Indicator count

    pthread_mutex_unlock(&poolMutex);

    return pdu;
}
```
