namespace Configuration {
    class Manager{
        private:
            static std::unordered_map<std::string, std::string> settings;
            static void loadFromFile(const std::string& fileName);
            static void saveToFile(const std::string& fileName);

        public:
            Manager();
            ~Manager();
            static void addSetting(const std::string& key, const std::string& value);
            static void removeSetting(const std::string& key);
            static void updateSetting(const std::string& key, const std::string& newValue);
            static std::string getSetting(const std::string& key);
    };
}

namespace Configuration {
    //load settings from JSON file into unordered_map
    void Manager::loadFromFile(const std::string& fileName){
        std::ifstream ifs(fileName);
        Json::Reader reader;
        Json::Value obj;
        reader.parse(ifs, obj); // parse and read JSON object from stream

        for (auto const& id : obj.getMemberNames()){
            settings[id] = obj[id].asString();
        }
    }

    void Manager::saveToFile(const std::string& fileName){
        Json::Value json;
        for(auto &setting: settings) {
          json[setting.first] = setting.second;
        }

        std::ofstream ofs(fileName);
        ofs << json;
    }

    //initialize static member variable
    std::unordered_map<std::string, std::string> Manager::settings = {};

    Manager::Manager(){
        loadFromFile("config.json"); 
    }

    Manager::~Manager(){
        saveToFile("config.json"); 
    }

    void Manager::addSetting(const std::string& key, const std::string& value){
        settings[key] = value;
    }

    void Manager::removeSetting(const std::string& key){
        if (settings.find(key) != settings.end())
            settings.erase(key);
    }

    void Manager::updateSetting(const std::string& key, const std::string& newValue){
        addSetting(key, newValue);
    }

    std::string Manager::getSetting(const std::string& key){
        if (settings.find(key) != settings.end()) {
            return settings[key];
        } else{
            return ""; //consider throwing an exception or handling the error more gracefully
        }
    }
}
``` 
