        int CRCFLAG;
    } CRC_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct cache_entry {
    char* key;
    void* value;
    struct cache_entry *next, *prev;
} cache_entry;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // for thread safety
cache_entry *head, *tail;  // for caching recent entries

void add_to_cache(char* key, void* value) {
    pthread_mutex_lock(&lock);

    cache_entry *new = malloc(sizeof(cache_entry));
    new->key = strdup(key);
    new->value = value;
    new->next = NULL;
    new->prev = tail;

    if (tail) {
        tail->next = new;
    } else {
        head = new;
    }
    tail = new;

    pthread_mutex_unlock(&lock);
}

void* get_from_cache(char* key) {
    pthread_mutex_lock(&lock);

    for (cache_entry *curr = head; curr != NULL; curr = curr->next) {
        if (strcmp(key, curr->key) == 0) {
            pthread_mutex_unlock(&lock);
            return curr->value;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

char* md5(const char *str) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str, strlen(str), (unsigned char*)&digest);    

    char *mdString = malloc(33);
    for(int i = 0; i < 16; ++i)
         sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);

    return mdString;
}
``` 

