['Here's a basic implementation of such a function in C using an array of struct pointers for memory management:

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct PDU {
    int UE_ID;
    int time_slot_index;
    int RSSI[8];  // Assuming max 8 antennas for simplicity
} PDU;

typedef struct LTEList {
    pthread_mutex_t lock;
    PDU **PDUs;
    size_t size;
    size_t capacity;
} LTEList;

LTEList *initialize() {
    LTEList *list = malloc(sizeof(LTEList));
    pthread_mutex_init(&list->lock, NULL);
    list->capacity = 1024;  // Starting with an arbitrary size, can be adjusted as needed
    list->PDUs = malloc(list->capacity * sizeof(PDU*));
    list->size = 0;
    return list;
}

void add_pdu(LTEList *list, PDU *new_pdu) {
    pthread_mutex_lock(&list->lock);  // Critical section to avoid concurrent modification

    if (list->size == list->capacity) {
        list->PDUs = realloc(list->PDUs, 2 * list->capacity * sizeof(PDU*));
        if (!list->PDUs) {
            printf("Failed to reallocate memory for PDUs\n");
            exit(1);  // Or handle error as needed
        }
        list->capacity *= 2;
    }

    list->PDUs[list->size++] = new_pdu;

    pthread_mutex_unlock(&list->lock);
}

void free_lte_list(LTEList *list) {
    for (int i = 0; i < list->size; ++i) {
        free(list->PDUs[i]);  // Free individual PDUs
    }

    free(list->PDUs);  // Free array of pointers
    pthread_mutex_destroy(&list->lock);  // Clean up mutex
    free(list);  // Finally, free the list itself
}
```
The `initialize` function creates and initializes an empty LTEList. The `add_pdu` function adds a new PDU to the list. It uses a simple strategy for dynamic memory management: if adding a PDU would exceed the current capacity of the array, it doubles the size of the array using realloc. This approach minimizes memory fragmentation and avoids excessive reallocations in most scenarios.

