                    }
                    break; // If request is successful, exit loop and thread
                } catch (...) {
                    ++retryCount;
                    std::this_thread::sleep_for(std::chrono::milliseconds((int)delay));
                    delay *= BACKOFF_FACTOR; // Increase delay for exponential backoff
                }
            }
        }));
    }

    // Join all threads before exiting main thread
    for (auto& th : threads) {
        if (th.joinable())
            th.join();
    }
}
