```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

// UE context structure
typedef struct {
    uint32_t ue_id;
    uint8_t mac_ce_info;
    bool* ler_indicators; // Dynamic array of LER indicators
} ue_context;

// Function to save list of UE contexts to a binary file
void save_contexts(const char *filename, const ue_context *contexts, size_t count) {
    FILE* file = fopen(filename, "wb");

    if (file == NULL) {
        printf("Error opening the file.\n");
        return;
    }

    // Save the number of contexts
    fwrite(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count; ++i) {
        // Save each UE context's details
        fwrite(&contexts[i].ue_id, sizeof(uint32_t), 1, file);
        fwrite(&contexts[i].mac_ce_info, sizeof(uint8_t), 1, file);

        // Save the number of LER indicators
        size_t ler_count = sizeof(contexts[i].ler_indicators) / sizeof(bool);
        fwrite(&ler_count, sizeof(size_t), 1, file);

        // Save each LER indicator
        fwrite(contexts[i].ler_indicators, sizeof(bool), ler_count, file);
    }

    fclose(file);
}

// Function to load list of UE contexts from a binary file
ue_context* load_contexts(const char *filename, size_t *count) {
    FILE* file = fopen(filename, "rb");

    if (file == NULL) {
        printf("Error opening the file.\n");
        return NULL;
    }

    // Load the number of contexts
    fread(count, sizeof(size_t), 1, file);

    ue_context* contexts = malloc(*count * sizeof(ue_context));

    for (size_t i = 0; i < *count; ++i) {
        // Load each UE context's details
        fread(&contexts[i].ue_id, sizeof(uint32_t), 1, file);
        fread(&contexts[i].mac_ce_info, sizeof(uint8_t), 1, file);

        // Load the number of LER indicators
        size_t ler_count;
        fread(&ler_count, sizeof(size_t), 1, file);

        contexts[i].ler_indicators = malloc(ler_count * sizeof(bool));

        // Load each LER indicator
        fread(contexts[i].ler_indicators, sizeof(bool), ler_count, file);
    }

    fclose(file);
    return contexts;
}
```

Please remember to free the memory allocated for `ler_indicators` in each context after use. Also, this code assumes that there is a maximum limit for the number of UE contexts and LER indicators that can be stored in a file. For real-world applications, you would need to add additional error checking and handling mechanisms to handle potential issues such as insufficient memory, too large files, etc.
