    }

    pthread_mutex_init(&list->mutex, NULL);
    list->capacity = initialCapacity;
    list->size = 0;
    list->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (list->data == NULL) {
        free(list);
        return NULL;
    }

    return list;
}

void destroy_list(DynamicList* list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->data);
    free(list);
}

void insert(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        // Double the capacity when full
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (newData == NULL) {
            // Error handling: couldn't allocate more memory
            pthread_mutex_unlock(&list->mutex);
            return;
        }

        list->data = newData;
        list->capacity = newCapacity;
    }

    // Add the element at the end and increase the size
    list->data[list->size++] = element;

    pthread_mutex_unlock(&list->mutex);
}

void removeByRNTI(DynamicList* list, int rnti) {
    pthread_mutex_lock(&list->mutex);

    // Find the index of the element to be removed (assuming RNTI is unique)
    for (size_t i = 0; i < list->size; ++i) {
