```javascript
const fs = require('fs').promises;
const path = require('path');

async function readFilesFromDir(dirPath) {
    const dirEntities = await fs.readdir(dirPath);
    let filesContent = {};

    for (let entity of dirEntities) {
        const entityPath = path.join(dirPath, entity);
        const stats = await fs.stat(entityPath);

        if (stats.isDirectory()) {
            const subFiles = await readFilesFromDir(entityPath);
            filesContent = Object.assign({}, filesContent, subFiles);
        } else if (stats.isFile()) {
            try {
                const content = await fs.readFile(entityPath, 'utf8');
                filesContent[entity] = content;
            } catch (error) {
                console.log(`Error reading file ${entity}: ${error}`);
            }
        }
    }

    return filesContent;
}
``` 

This code assumes that the directory path is valid and it has read permissions, you should handle these cases in your actual usage.
