["Here's a high-level implementation of the requirements you described using Node.js. This code includes caching, handling multiple concurrent requests, regex patterns for matching book names in multiple languages, support for partial matches, and an option to disable them.

```javascript
const cache = new Map(); // Cache for storing processed texts
let cacheSize = 0; // Current size of the cache
let maxCacheSize = 10000; // Maximum size of the cache before it starts evicting old entries

function countBookNames(text, languageCode='en', allowPartialMatches=true) {
    if (cache.has(text)) return cache.get(text); // If the text is in the cache, return its value from there

    const regexes = getLanguageSpecificRegexes(languageCode, allowPartialMatches); // Get language-specific regex patterns
    let counts = {}; // Object to store book name counts

    for (let regex of regexes) {
        let matches = text.match(regex); // Find all matches for this regex in the text

        if (matches) {
            for (let match of matches) {
                if (!counts[match]) counts[match] = 0; // If this book name is not yet in the object, add it with a count of 0
                counts[match]++; // Increment the count for this book name
            }
        }
    }

    let filteredCounts = {}; // Object to store only books that appear more than once

    for (let key in counts) {
        if (counts[key] > 1) filteredCounts[key] = counts[key]; // If this book name appears more than once, add it to the new object
    }

    // Update the cache and its size
    cache.set(text, filteredCounts);
    cacheSize += text.length;

    if (cacheSize > maxCacheSize) {
        let oldestEntry = cache.keys().next().value; // Get the key of the oldest entry in the cache
        cacheSize -= Buffer.byteLength(oldestEntry, 'utf-8'); // Subtract its size from the total cache size
        cache.delete(oldestEntry); // Delete the oldest entry to make space for new entries
    }

    return Object.keys(filteredCounts).length > 5 ? filteredCounts : {}; // Return the object of book names and their frequencies if more than 5 unique books are found, otherwise an empty object
}
```
Note: You need to define `getLanguageSpecificRegexes()` function which returns language-specific regex patterns for matching book names. This function should be implemented based on your application's specific needs.
