void manageDataStructures(size_t datasetSize, int minRange, int maxRange) {
    if (datasetSize == 0 || minRange >= maxRange) {
        return;  // Invalid input case
    }

    srand((unsigned int) time(NULL));  // Initialize random seed

    long* offsetValues = malloc(sizeof(long) * datasetSize);
    if (offsetValues == NULL) {
        return;  // Failed to allocate memory for offset values
    }

    int* keys = calloc(datasetSize, sizeof(int));
    if (keys == NULL) {
        free(offsetValues);
        return;  // Failed to allocate memory for keys
    }

    Record* records = malloc(sizeof(Record) * datasetSize);
    if (records == NULL) {
        free(offsetValues);
        free(keys);
        return;  // Failed to allocate memory for records
    }

    Metadata* metadata = calloc(datasetSize, sizeof(Metadata));
    if (metadata == NULL) {
        free(offsetValues);
        free(keys);
        free(records);
        return;  // Failed to allocate memory for metadata
    }

    for (size_t i = 0; i < datasetSize; ++i) {
        records[i].value = rand() % (maxRange - minRange + 1) + minRange;  // Set a random value within the given range

        metadata[i].record = &records[i];  // Associate record with corresponding metadata
        metadata[i].importanceLevel = 0;  // Initialize importance level to zero
    }

    free(offsetValues);
    free(keys);
    free(records);
    free(metadata);
}
```
