class RateLimiter {
public:
  RateLimiter(size_t maxCount, std::chrono::seconds interval) :
    count_(0), maxCount_(maxCount), interval_(interval), lastTime_(std::chrono::steady_clock::now()) {}

  void wait() {
    ++count_;
    if (count_ > maxCount_) {
      auto now = std::chrono::steady_clock::now();
      if (now - lastTime_ < interval_) {
        std::this_thread::sleep_for(interval_);
        count_ = 1;
        lastTime_ = now;
      } else {
        count_ = 0; // Start a new window.
      }
    }
  }

private:
  size_t count_;
  const size_t maxCount_;
  const std::chrono::seconds interval_;
  std::chrono::time_point<std::chrono::steady_clock> lastTime_;
};
