int countDisjointPairs(int* array, int length) {
  clock_t start, end;
  double cpu_time_used;

  int disjointCount = 0;

  for (int i=0; i<length-1; ++i) {
    start = clock(); // Start timer.

    pthread_mutex_lock(&lock); // Lock before accessing shared data.

    if(array[i] != array[i+1]) disjointCount++; 

    pthread_mutex_unlock(&lock); // Unlock after accessing shared data.

    end = clock(); // End timer.

    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time taken for pair %d-%d: %f ms\n", array[i], array[i+1], cpu_time_used); // Print time.
  }

  return disjointCount;
}
