#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <jansson.h> // JSON parsing library
#include <stdio.h>  // FILE, fopen, etc.

typedef struct sensor_data {
    double value;
    char* identifier;
} sensor_data;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the sensor data array
sensor_data* init_sensors(int num, double min, double max) {
    srand(time(0)); // Seed for random number generation

    if (num <= 0) {
        fprintf(stderr, "Error: Number of sensors must be positive.\n");
        return NULL;
    }

    sensor_data* data = malloc(num * sizeof(sensor_data)); // Allocate memory for array

    if (data == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory.\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);  // Lock mutex for thread safety
    for (int i = 0; i < num; i++) {
        data[i].value = min + ((double)rand() / RAND_MAX) * (max - min); // Generate random value

        int len = rand() % 16 + 1; // Generate random identifier length between 1 and 16
        data[i].identifier = malloc(len+1); // Allocate memory for string

        if (data[i].identifier == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory.\n");
            return NULL;
        }

        for (int j = 0; j < len; j++) { // Generate random string
            data[i].identifier[j] = 'a' + rand() % 26;
        }
        data[i].identifier[len] = '\0'; // Null terminator
    }
    pthread_mutex_unlock(&lock); // Unlock mutex after initialization

    return data;
}

// Function to read configuration from JSON file and initialize sensors
sensor_data* init_sensors_from_config(const char *filename) {
    json_t *root, *num, *min, *max;
    json_error_t error;

    // Open and parse the JSON file
    root = json_load_file(filename, 0, &error);

    if(!json_is_object(root)) {
        fprintf(stderr, "Error: File contains no object\n");
        return NULL;
    }

    // Get configuration parameters from the JSON file
    num = json_object_get(root, "num");
    min = json_object_get(root, "min");
    max = json_object_get(root, "max");

    if(!json_is_integer(num) || !json_is_number(min) || !json_is_number(max)) {
        fprintf(stderr, "Error: Invalid configuration parameters\n");
        return NULL;
    }

    // Initialize sensors with parsed configuration
    sensor_data* data = init_sensors(json_integer_value(num), json_real_value(min), json_real_value(max));

    // Cleanup
    json_decref(root);

    return data;
}
```
This example uses the Jansson library for JSON parsing, which is a C library for encoding, decoding and manipulating JSON data. Make sure you have this installed before compiling the code. Also note that error handling in this example is quite basic - real-world applications should be more thorough when it comes to dealing with errors.
