#define MAX_UE 100000
static UEContext ueCtx[MAX_UE];
static int ueCount = 0;
static pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;

int validateInputs(int ueId, int tac) {
    if (ueId < 1 || ueId > MAX_UE) {
        printf("Invalid UE ID: %d\n", ueId);
        return -1;
    }

    if (tac < 0 || tac > 65535) {
        printf("Invalid TAC: %d\n", tac);
        return -1;
    }

    return 0;
}

int addUEContext(int ueId, int tac, float rsrp, float rsrq, float sinr) {
    if (validateInputs(ueId, tac) != 0) {
        return -1;
    }

    pthread_mutex_lock(&globalLock);

    if (ueCount < MAX_UE) {
        UEContext* ctx = &ueCtx[ueCount++];
        ctx->key.ueId = ueId;
        ctx->key.tac = tac;
        ctx->meas.rsrp = rsrp;
        ctx->meas.rsrq = rsrq;
        ctx->meas.sinr = sinr;

        pthread_mutex_init(&ctx->lock, NULL); // Initialize lock
    } else {
        printf("Max UE contexts reached\n");
        return -1;
    }

    pthread_mutex_unlock(&globalLock);

    return 0;
}
