int initAndPopulateList(int UE_ID, int Cell_ID) {
    pthread_mutex_lock(&mutex);

    LTE_RRC_Connected_Config* newItem = (LTE_RRC_Connected_Config*) malloc(sizeof(LTE_RRC_Connected_Config));
    if (!newItem) {
        pthread_mutex_unlock(&mutex);
        return -1; // Error: Memory allocation failed.
    }

    newItem->UE_ID = UE_ID;
    newItem->Cell_ID = Cell_ID;
    newItem->config = (struct RRC_Configuration*) malloc(sizeof(struct RRC_Configuration));
    if (!newItem->config) {
        free(newItem);
        pthread_mutex_unlock(&mutex);
        return -1; // Error: Memory allocation failed.
    }

    // Set other fields of newItem...

    list = (LTE_RRC_Connected_Config*) realloc(list, sizeof(LTE_RRC_Connected_Config) * (size + 1));
    if (!list && size != 0) {
        free(newItem->config);
        free(newItem);
        pthread_mutex_unlock(&mutex);
        return -1; // Error: Memory allocation failed.
    }

    list[size] = *newItem;
    size++;

    pthread_mutex_unlock(&mutex);
    free(newItem->config);
    free(newItem);
    return 0; // Success.
}
