typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

void populateList(Node **head, int n) {
    srand(time(0));
    jmp_buf env;
    setjmp(env);
    int i = 0;
    while (i < n) {
        NFAPI_CRC_INDICATION_PDU_T *newData = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newData) {
            printf("Allocation failed. Cleaning up...\n");
            freeList(head);
            longjmp(env, 1);
        }
        newData->RX_UE_INFORMATION_TAG = malloc(16);
        newData->RNTI = rand();
        newData->CRC_INDICATION_REL8_TAG.CRCFLAG = rand();

        Node *newNode = malloc(sizeof(Node));
        if (!newNode) {
            printf("Allocation failed. Cleaning up...\n");
            freeList(head);
            longjmp(env, 1);
        }
        newNode->data = newData;
        newNode->next = *head;
        *head = newNode;
        ++i;
    }
}

void freeList(Node **head) {
    Node *current = *head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->data);
        free(temp);
    }
    *head = NULL;
}
```
