    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    int capacity;
    int size;
    NFAPI_CRC_INDICATION_PDU_T *data;
} DynamicList;

DynamicList createList(int initialCapacity) {
    DynamicList list = {
        .capacity = initialCapacity,
        .size = 0,
        .data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T)),
    };
    pthread_mutex_init(&list.mutex, NULL);
    return list;
}

void resizeList(DynamicList* list, int newCapacity) {
    NFAPI_CRC_INDICATION_PDU_T *newData = (NFAPI_CRC_INDICATION_PDU_T*) malloc(newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(newData, list->data, list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(list->data);
    list->capacity = newCapacity;
    list->data = newData;
}

void addToList(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        resizeList(list, list->capacity * 2);
    }
    list->data[list->size++] = item;
    pthread_mutex_unlock(&list->mutex);
}
```
In this implementation, a mutex is used to protect the critical section where `addToList` and `resizeList` are called.  This ensures that only one thread can execute these functions at a time, preventing race conditions. The function `createList` initializes a new list with the specified initial capacity. If the size of the list exceeds its current capacity, the function `resizeList` doubles the capacity and copies all existing data to the new array.

This implementation assumes that you are using POSIX threads (pthreads) for thread safety. However, other methods such as mutexes in C++11 or std::mutex in C++ can be used depending on your platform's support for concurrency and synchronization primitives. Also, random number generation has not been addressed here as it would likely depend on the requirements of your specific use case.
