function refreshFields(fieldIds, resourceId, url) {
    var promises = fieldIds.map(id => {
        return $http({
            method: 'GET',
            url: `${url}?resourceId=${resourceId}&fieldId=${id}`
        });
    });

    $q.all(promises)
        .then((results) => {
            // update the dialog fields with the results if successful
            results.forEach((result, index) => {
                if (result.success) {
                    var fieldId = fieldIds[index];
                    $('#' + fieldId).val(result.data);
                }
            });
        })
        .catch(() => {
            // handle the error here or retry logic if needed
        });
