NFAPI_CRC_INDICATION_PDU_T *create(int RX_UE_INFORMATION_TAG, int RNTI, unsigned char CRCFLAG) {
    pthread_mutex_lock(&lock);
    if (current_memory + sizeof(NFAPI_CRC_INDICATION_PDU_T) + sizeof(CRC_INDICATION_REL8_TAG) > MAX_MEMORY) {
        pthread_mutex_unlock(&lock);
        return NULL;  // No enough memory available
    }

