#include <errno.h>

typedef struct Record {
    int value;
} Record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocateMemory(size_t offsetsSize, size_t keysSize, size_t recordsSize) {
    // Lock the mutex to ensure thread safety.
    pthread_mutex_lock(&mutex);

    long *offsets = malloc(offsetsSize * sizeof(*offsets));
    if (offsets == NULL) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    int *keys = calloc(keysSize, sizeof(*keys));
    if (keys == NULL) {
        free(offsets);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    Record *records = malloc(recordsSize * sizeof(*records));
    if (records == NULL) {
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < recordsSize; ++i) {
        records[i].value = rand() % 100 + 1;
    }

    // Unlock the mutex after memory allocation.
    pthread_mutex_unlock(&mutex);

    return records;
}

void freeMemory(long *offsets, int *keys, Record *records) {
    // Lock the mutex to ensure thread safety.
    pthread_mutex_lock(&mutex);

    free(offsets);
    free(keys);
    free(records);

    // Unlock the mutex after memory deallocation.
    pthread_mutex_unlock(&mutex);
}
