        list->capacity *= 2;
        list->contexts = realloc(list->contexts, sizeof(UEContext*) * list->capacity);
    }
    UEContext* context = malloc(sizeof(UEContext));
    context->id = id;
    context->messages = messages;
    list->contexts[list->size] = context;
    list->size++;
}

void delete_ue_context(UEList* list, int index) {
    if (index < 0 || index >= list->size) return;
    free(list->contexts[index]->messages);
    free(list->contexts[index]);
    // Shift all elements down to fill the gap.
    for (int i = index; i < list->size - 1; i++) {
        list->contexts[i] = list->contexts[i + 1];
    }
    list->size--;
}
