#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct ue_context {
    int ue_id;
    struct {
        int rrc_state;
        int cell_id;
        int tac;
    } rrc_connection_info;
    struct {
        float rsrp;
        float rsrq;
        int neighbor_cell_id;
    } measurement_report[5];
    struct ue_context *next;
} LTE_UE_CONTEXT_T;

typedef struct context_list {
    atomic_int count; // To track the number of contexts in the list.
    pthread_mutex_t lock; // For thread safety when adding or removing contexts.
    LTE_UE_CONTEXT_T *head; 
} CONTEXT_LIST_T;

// Function to create and populate a list of UE contexts.
void CreateAndPopulateLteUeContextList(int number_of_ue, CONTEXT_LIST_T* list) {
    if (number_of_ue < 0 || number_of_ue > 100000) return; // Input validation for the number of UE Contexts.

    pthread_mutex_init(&list->lock, NULL); 

    LTE_UE_CONTEXT_T *current = list->head;

    for(int i = 0; i < number_of_ue; i++) {
        if(i == 0) {
            current = malloc(sizeof(LTE_UE_CONTEXT_T)); // Allocate memory for the first UE Context.
            list->head = current; 
        } else {
            current->next = malloc(sizeof(LTE_UE_CONTEXT_T)); // Allocate memory for subsequent UE Contexts.
            current = current->next;
        }

        // Populate the UE Context with data from external sources (e.g., databases or network APIs).
        current->ue_id = i; 
        current->rrc_connection_info.rrc_state = 0;
        current->rrc_connection_info.cell_id = 123456789;
        current->rrc_connection_info.tac = 23456;

        for(int j=0; j<5; j++) {
            current->measurement_report[j].rsrp = -113 + (float)(rand() % 3);
            current->measurement_report[j].rsrq = 0.0;
            current->measurement_report[j].neighbor_cell_id = 543219876;
        }
    }

    atomic_fetch_add(&list->count, number_of_ue); // Increase the context count.
}

// Function to clean up and free memory of a list of UE contexts.
void CleanupAndFreeLteUeContextList(CONTEXT_LIST_T* list) {
    pthread_mutex_lock(&list->lock); 

    LTE_UE_CONTEXT_T *current = list->head;
    while (current != NULL) {
        LTE_UE_CONTEXT_T *next = current->next; // Store the next node before freeing memory.
        free(current); 
        atomic_fetch_sub(&list->count, 1); // Decrease the context count.

        current = next;
    }

    pthread_mutex_unlock(&list->lock);
}
```
