void allocate_arrays(int num) {
    if (num < 1) return;  // Gracefully handle zero or negative numbers

    long* offsets = malloc(sizeof(long)*num);
    if (!offsets) exit(EXIT_FAILURE);

    int* keys = calloc(num, sizeof(int));
    if (!keys) {
        free(offsets);
        exit(EXIT_FAILURE);
    }

    Record *records = malloc(sizeof(Record)*num);
    if(!records){
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));  // Seed the random number generator

    for (int i = 0; i < num; ++i){
        records[i].value = rand() % 101;  // Generate a random value between [0,100]

        char* strIndex = malloc(20);
        if(!strIndex) {
            free(offsets);
            free(keys);
            for (int j = 0; j < i; ++j){
                free(records[j].str);
            }
            free(records);
            exit(EXIT_FAILURE);
        }

        sprintf(strIndex, "%d",i);  // Convert the index to a string
        records[i].str = strIndex;
    }

    // Use your arrays here...

    for (int i = 0; i < num; ++i){
      free(records[i].str);
    }
    free(offsets);
    free(keys);
    free(records);
}
