// Serialize the list to a file.
void serialize(NFAPI_CRC_INDICATION_PDU_T *list, size_t count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&lock);
    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    pthread_mutex_unlock(&lock);

    fclose(file);
}

// Deserialize the list from a file.
void deserialize(NFAPI_CRC_INDICATION_PDU_T **list, size_t *count, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&lock);
    // Get the size of the file.
    fseek(file, 0L, SEEK_END);
    *count = ftell(file) / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Allocate memory for the list.
    *list = malloc(*count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        perror("Failed to allocate memory");
        return;
    }

    // Read from the file into the list.
    rewind(file);
    fread(*list, sizeof(NFAPI_CRC_INDICATION_PDU_T), *count, file);
    pthread_mutex_unlock(&lock);

    fclose(file);
}
```

