['Here is a basic implementation in C that might meet your requirements. This sample assumes some common data structures used by LTE Radio Link Control (RLC) as specified in 3GPP specifications. The memory allocation uses the `calloc` function for initialization to zero, and freeing of the allocated memory is handled using the `free` function.

```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int rlc_sn;
} RLC_SN;

typedef struct {
    unsigned char *data;
    size_t length;
} RLC_DATA_PDU;

typedef struct {
    RLC_SN sn;
    RLC_DATA_PDU pdu;
} LTE_RLC_PDU;

LTE_RLC_PDU* create_lte_rlc_pdus(int num, int(*get_external_data)(void)) {

    // Allocate memory for the array of PDUs
    LTE_RLC_PDU *pdus = calloc(num, sizeof(LTE_RLC_PDU));
    if (pdus == NULL) {
        return NULL;  // Error: Memory allocation failed.
    }

    srand((unsigned int) time(NULL));

    for (int i = 0; i < num; ++i) {

        pdus[i].sn.rlc_sn = rand();

        // Get the data size from an external source if available, otherwise use a random value between 10 and 100 bytes
        int data_size = (get_external_data != NULL) ? get_external_data() : (rand() % 91 + 10);

        pdus[i].pdu.length = data_size;
        pdus[i].pdu.data = calloc(pdus[i].pdu.length, sizeof(unsigned char));

        if (pdus[i].pdu.data == NULL) {
            // Error: Memory allocation failed. Free previously allocated memory and return NULL
            for (int j = 0; j < i; ++j) {
                free(pdus[j].pdu.data); 
            }
            free(pdus);
            return NULL;
        }

        // Populate the PDU data with random values
        for (size_t j = 0; j < pdus[i].pdu.length; ++j) {
            pdus[i].pdu.data[j] = rand() % 256;
        }
    }

    return pdus;
}
```
