['Here is an example in C which demonstrates how you can implement this task with a thread-safe linked list using pthreads and a serialization/deserialization mechanism to files with locks for mutual exclusion:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <string.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node *head = NULL;
FILE* file;

void serialize() {
    pthread_mutex_lock(&lock);
    if ((file = fopen("data.txt", "w")) == NULL) {
        printf("File open failed\n");
        return;
    }

    Node *currentNode = head;
    while (currentNode != NULL) {
        fwrite(&(currentNode->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        currentNode = currentNode->next;
    }

    fclose(file);
    pthread_mutex_unlock(&lock);
}

void deserialize() {
    pthread_mutex_lock(&lock);
    if ((file = fopen("data.txt", "r")) == NULL) {
        printf("File open failed\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        addElement(data);
    }

    fclose(file);
    pthread_mutex_unlock(&lock);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node *newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    newNode->data = data;
    newNode->next = NULL;

    return newNode;
}

void addElement(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);
    Node *newNode = createNode(data);
    if (head == NULL) {
        head = newNode;
    } else {
        Node *currentNode = head;
        while (currentNode->next != NULL && currentNode->data.RNTI != data.RNTI) {
            currentNode = currentNode->next;
        }

        if (currentNode->data.RNTI != data.RNTI) {
            currentNode->next = newNode;
        } else {
            printf("Element with same RNTI already exists\n");
            free(newNode);
        }
    }
    pthread_mutex_unlock(&lock);
}

void removeElementByRNTI(int rnti) {
    pthread_mutex_lock(&lock);
    if (head == NULL) return;

    if (head->data.RNTI == rnti) {
        Node *temp = head;
        head = head->next;
        free(temp);
    } else {
        Node *currentNode = head;

        while (currentNode->next != NULL && currentNode->next->data.RNTI != rnti) {
            currentNode = currentNode->next;
        }

        if (currentNode->next == NULL) {
            printf("Element with RNTI not found\n");
        } else {
            Node *temp = currentNode->next;
            currentNode->next = temp->next;
            free(temp);
        }
    }
    pthread_mutex_unlock(&lock);
}
```
This code implements a thread-safe singly linked list with RNTI based duplication check, serialization and deserialization to file system. It also includes error handling for memory allocation failures. The lock is used while accessing/modifying the head of the linked list and during file operations.
']

