size_t size = 0;

pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

int initList(size_t initialCapacity) {
    if (initialCapacity == 0) {
        return -1;  // Invalid capacity
    }

    contexts = malloc(sizeof(UE_Context_T) * initialCapacity);
    if (contexts == NULL) {
        return -2;  // Memory allocation failed
    }

    capacity = initialCapacity;
    size = 0;

    return 0;
}

int addUEContext(/* Define parameters here */) {
    pthread_mutex_lock(&listMutex);

    if (size == capacity) {
        // If the list is full, resize it by doubling its capacity
        size_t newCapacity = capacity * 2;
        UE_Context_T* resizedContexts = realloc(contexts, sizeof(UE_Context_T) * newCapacity);

        if (resizedContexts == NULL) {
            pthread_mutex_unlock(&listMutex);
            return -2;  // Memory allocation failed
        }

        contexts = resizedContexts;
        capacity = newCapacity;
    }

    // Populate the new context at position 'size' with your parameters or defaults
    // contexts[size] = ...

    size++;

    pthread_mutex_unlock(&listMutex);

    return 0;
}
