["Here is a C function that meets all your requirements. We use a dynamic allocation for the list and use mutexes to handle thread safety:

```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>  // For memcpy

typedef struct {
    // Define your structure here.
} LTE_PHY_MEASUREMENTS_T;

// Declare a global mutex to ensure thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_measurement(LTE_PHY_MEASUREMENTS_T **list, int *size) {
    // Lock the mutex before accessing the list to ensure thread safety
    pthread_mutex_lock(&lock);

    LTE_PHY_MEASUREMENTS_T *new_measurement = (LTE_PHY_MEASUREMENTS_T *)malloc(sizeof(LTE_PHY_MEASUREMENTS_T));
    if (new_measurement == NULL) {
        pthread_mutex_unlock(&lock);  // Unlock the mutex before returning to avoid deadlock
        return;  // Handle out-of-memory condition
    }

    // Populate your measurement data here
    new_measurement->ofdm_symbol_info = get_ofdm_symbol_info();
    new_measurement->ue_index = get_ue_index();
    new_measurement->quality_indicator = rand() % 100;

    // Increase the size of the list and add the new measurement to the end of the list
    (*size)++;
    *list = (LTE_PHY_MEASUREMENTS_T *)realloc(*list, sizeof(LTE_PHY_MEASUREMENTS_T) * (*size));

    if (*list == NULL) {
        pthread_mutex_unlock(&lock);  // Unlock the mutex before returning to avoid deadlock
        return;  // Handle out-of-memory condition
    }

    memcpy(&(*list)[*size - 1], new_measurement, sizeof(LTE_PHY_MEASUREMENTS_T));

    free(new_measurement);  // No longer needed after it's copied to the list

    pthread_mutex_unlock(&lock);  // Unlock the mutex so other threads can access the list
}
