        for(size_t j = 0; j < numDci; ++j) {
            phyFrame->dciMessages[j] = dciMessages[i][j];  // Set DCI messages
        }

        // Create new Node and add to linked list
        Node *node = malloc(sizeof(*node));
        if (node == NULL) {
            return NULL;  // Handle memory allocation error
        }

        node->phyFrame = phyFrame;
        node->next = NULL;

        if (head == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
