    pthread_mutex_lock(&lock);  // Locking to ensure thread safety
    UE_Transmission_PDU_T* head = NULL;
    UE_Transmission_PDU_T* tail = NULL;

    for (int i = 0; i < numOfPDUs; i++) {
        int payloadSize = rand() % (maxSize - minSize + 1) + minSize;  // random size between min and max

        MAC_Header macAddress = generateRandomMacAddress();
        Data_Payload dataPayload = generateRandomPayload(payloadSize);

        UE_Transmission_PDU_T* newNode = (UE_Transmission_PDU_T*) malloc(sizeof(UE_Transmission_PDU_T));
        if (!newNode) {  // handle memory allocation failure
            pthread_mutex_unlock(&lock);  // Release lock before terminating
            printf("Memory allocation failed\n");
            exit(-1);
        }

        newNode->header = macAddress;
        newNode->payload = dataPayload;
        newNode->next = NULL;

        if (!head) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    pthread_mutex_unlock(&lock);  // Release lock after function execution
    return head;
}
