['```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct MAC_Header {
    unsigned char mac_address[6];
} MAC_Header;

typedef struct Data_Payload {
    size_t size;
    void* data;
} Data_Payload;

typedef struct UE_Transmission_PDU_T {
    MAC_Header header;
    Data_Payload payload;
} UE_Transmission_PDU_T;

typedef struct QueueNode {
    UE_Transmission_PDU_T* pdu;
    struct QueueNode* next;
} QueueNode;

pthread_mutex_t queueMutex = PTHREAD_MUTEX_INITIALIZER;
atomic_size_t totalPayloadSize = 0;
QueueNode* queueHead = NULL;
QueueNode* queueTail = NULL;

// Function to create and populate a list of UE_Transmission_PDU_T structures
void createAndPopulateList(size_t numPDUs) {
    size_t remainingPayloadSize = 10000 - totalPayloadSize;
    while (numPDUs > 0 && remainingPayloadSize >= 100) {
        UE_Transmission_PDU_T* pdu = malloc(sizeof(UE_Transmission_PDU_T));
        if (!pdu) {
            // Handle memory allocation failure
            return;
        }

        for (int i = 0; i < 6; ++i) {
            pdu->header.mac_address[i] = rand() % 256;
        }

        size_t payloadSize = (rand() % 901) + 100; // Randomly generated between 100 and 1000 bytes
        if (remainingPayloadSize < payloadSize) {
            free(pdu);
            break;
        }

        pdu->payload.size = payloadSize;
        pdu->payload.data = malloc(payloadSize);
        if (!pdu->payload.data) {
            // Handle memory allocation failure
            free(pdu);
            return;
        }

        remainingPayloadSize -= payloadSize;

        pthread_mutex_lock(&queueMutex);
        totalPayloadSize += payloadSize;
        QueueNode* node = malloc(sizeof(QueueNode));
        if (!node) {
            // Handle memory allocation failure
            free(pdu->payload.data);
            free(pdu);
            pthread_mutex_unlock(&queueMutex);
            return;
        }

        node->pdu = pdu;
        node->next = NULL;
        if (queueTail) {
            queueTail->next = node;
            queueTail = node;
        } else {
            queueHead = queueTail = node;
        }

        pthread_mutex_unlock(&queueMutex);

        --numPDUs;
    }
}
