    u_char addr[4]; // Assuming IPv4 addresses
} ip_addr;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
ip_addr* dns_cache[1024] = {NULL};

int gethostbyname(const char *hostname, ip_addr* result) {
    pthread_mutex_lock(&lock);
    if (dns_cache[hostname] != NULL) { // If host is in cache, return it
        memcpy(result, dns_cache[hostname], sizeof(ip_addr));
        pthread_mutex_unlock(&lock);
        return 0;
    } else { // Else, resolve DNS and add to cache
        struct hostent *h = gethostbyname(hostname);
        if (h == NULL) {
            herror("gethostbyname");
            pthread_mutex_unlock(&lock);
            return -1;
        } else {
            dns_cache[hostname] = malloc(sizeof(ip_addr)); // Remember to free this later
            memcpy(dns_cache[hostname], h->h_addr, sizeof(ip_addr));
            memcpy(result, dns_cache[hostname], sizeof(ip_addr));
            pthread_mutex_unlock(&lock);
            return 0;
        }
    }
}

