// Function to add nodes in ascending order based on RNTI value.
void addToListInOrder(NFAPI_CRC_INDICATION_PDU_T *node) {
    if (list == NULL || list->RNTI > node->RNTI) { // If first element or smaller than current head, make it the new head.
        node->next = list;

