class PHYList {
private:
    std::vector<LTE_PHY_PDU> list_;
    mutable std::mutex mtx_;
public:
    void insert(const LTE_PHY_PDU& pdu) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = std::lower_bound(list_.begin(), list_.end(), pdu, 
                                   [](const LTE_PHY_PDU& lhs, const LTE_PHY_PDU& rhs) {
                                       return lhs.ueID < rhs.ueID; });
        if (it == list_.end() || it->ueID != pdu.ueID) {
            list_.insert(it, pdu);
        } else {
            // Handle UE ID collision here, or throw exception, etc.
        }
    }

    void removeByUEID(int ueID) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = std::find_if(list_.begin(), list_.end(), [&](const LTE_PHY_PDU& pdu){ return pdu.ueID == ueID; });
        if (it != list_.end()) {
            list_.erase(it);
        }
    }
};
```

