For JavaScript reduce method, Node.js has an inbuilt async version of Array.prototype.reduce() that you can use. Here is how you would use it with asynchronous callbacks:

```javascript
const reduceAsync = (arr, initVal, cb) => new Promise((resolve, reject) => {
  if (!Array.isArray(arr)) return reject('Input must be an array');

  const len = arr.length;
  let acc = initVal;

  const reduceStep = i => {
    // Handle end of the array: resolve with accumulator
    if (i === len) return resolve(acc);

    cb(acc, arr[i])
      .then(res => {
        acc = res;
        setImmediate(() => reduceStep(i + 1));  // async call to not block the main thread
      })
      .catch(reject)
  };

  reduceStep(0);  // start with first element of array
});
```
