    newNode->context = context;
    newNode->next = list_head;
    list_head = newNode;

    pthread_mutex_unlock(&lock);
}

UeContext* getList() {
    pthread_mutex_lock(&lock);

    Node* current = list_head;
    UeContext* contextArray = malloc(sizeof(UeContext) * countNodes());
    int index = 0;

    while (current != NULL) {
        contextArray[index++] = current->context;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);

    return contextArray;
}

int countNodes() {
    int count = 0;
    Node* current = list_head;

    while (current != NULL) {
        count++;
        current = current->next;
    }

    return count;
}
