typedef struct RLC_DATA_PDU {
    size_t data_size;
    char* data;
} RLC_DATA_PDU;

typedef struct LTE_RLC_PDU {
    int rlc_sn;
    RLC_DATA_PDU* pdu;
    struct LTE_RLC_PDU *next, *prev;  // For doubly linked list
} LTE_RLC_PDU;

#define MAX_PDUS 10000
LTE_RLC_PDU* head = NULL;
LTE_RLC_PDU* tail = NULL;
size_t pdu_count = 0;

void* safeMalloc(size_t size) {
    void* mem = malloc(size);
    if (mem == NULL && size != 0) {
        exit(EXIT_FAILURE); // or any other error handling method you prefer.
    }
    return mem;
}

LTE_RLC_PDU* createNewNode() {
    LTE_RLC_PDU *node = safeMalloc(sizeof(*node));

    node->rlc_sn = pdu_count + 1;  // RLC Serial Numbers start from 1.
    node->pdu = safeMalloc(sizeof(*(node->pdu)));
    srand(time(0));
    size_t dataSize = 10 + rand() % 91; // generate a random number between 10 and 100.

    node->pdu->data = safeMalloc(dataSize);
    for (size_t i = 0; i < dataSize; ++i) {
        node->pdu->data[i] = rand() % 256; // initialize with random bytes.
    }

    return node;
}

int appendNodeToList(LTE_RLC_PDU *node) {
    if (pdu_count >= MAX_PDUS) return -1;

    if (head == NULL && tail == NULL) { // list is empty.
        head = node;
        tail = node;
    } else {
        tail->next = node;
        node->prev = tail;
        tail = node;
    }
    ++pdu_count;
    return 0;
}
```
The `safeMalloc` function handles potential null pointer dereferences by checking if the allocation was successful. It exits the program upon failure, but you could also handle errors differently according to your needs.

Please keep in mind that this code is a starting point and it needs to be extended with error handling and other necessary parts to fit your requirements. Also, remember to free all dynamically allocated memory before the end of the program execution using `free` function.
