int cache[1000] = {0}; // Cache for RNTI values

NFAPI_CRC_INDICATION_PDU_T *generateList(unsigned int N) {
    if (N > 1000) {
        printf("Error: List size exceeds maximum of 1000.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator
    pthread_mutex_lock(&lock); // Lock mutex for thread-safety

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N*sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (unsigned int i = 0; i < N; ++i) {
        // Generate unique RNTI by checking cache and re-generating if necessary
        int rnti = -1;
        while (rnti == -1 || cache[rnti] == 1) 
