    for (int i = 0; i < count; ++i) {
        contextArray[i].ue_id = i + 1;  // Assign a unique ID to each UE
        contextArray[i].mac_ce.crc_flag = rand() % 2;  // Randomly set CRC flag

        printf("UE Context created with id: %d, crc_flag: %d\n", 
               contextArray[i].ue_id, contextArray[i].mac_ce.crc_flag);
    }

    contextCount = count;
}

void modifyContext(int index, int newId) {
    if (index < 0 || index >= contextCount) {
        printf("Invalid index.\n");
        return;
    }

    contextArray[index].ue_id = newId;  // Change the UE ID

    printf("UE Context modified. New id: %d\n", newId);
}

void deleteContext(int index) {
    if (index < 0 || index >= contextCount) {
        printf("Invalid index.\n");
        return;
    }

    // Shift all subsequent elements down to fill the gap, effectively "deleting" this element
    for (int i = index; i < contextCount - 1; ++i) {
        contextArray[i] = contextArray[i + 1];
    }

    --contextCount;  // Update count

    printf("UE Context deleted.\n");
}
```
