```cpp
#include <iostream>
#include <chrono>
#include <queue>
#include <cpr/cpr.h>
#include <boost/asio/steady_timer.hpp>
#include <nlohmann/json.hpp>

using json = nlohmann::json;

struct TemperatureSensorReading {
    int sensorId;
    std::chrono::system_clock::time_point timestamp;
    double temperature;
};

class LoggingService {
public:
    virtual ~LoggingService() = default;
    virtual bool LogSensorReading(const TemperatureSensorReading& reading) = 0;
};

class DefaultLoggingService : public LoggingService {
private:
    boost::asio::io_service io_;
    std::queue<std::chrono::system_clock::time_point> requestTimes_;
    std::unique_ptr<boost::asio::steady_timer> rateLimiter_;

public:
    DefaultLoggingService() : rateLimiter_(std::make_unique<boost::asio::steady_timer>(io_)) { }

    bool LogSensorReading(const TemperatureSensorReading& reading) override {
        auto now = std::chrono::system_clock::now();

        if (requestTimes_.size() < 100 || now - requestTimes_.front() > std::chrono::minutes(1)) {
            cpr::Post(cpr::Url{"http://example.com/log"},
                      cpr::Body{json{{"sensorId", reading.sensorId}, {"temperature", reading.temperature}}.dump()},
                      cpr::Header{{"Content-Type", "application/json"}});

            if (requestTimes_.size() == 100) {
                requestTimes_.pop();
                rateLimiter_->expires_at(now + std::chrono::minutes(1));
                rateLimiter_->async_wait([this](const boost::system::error_code& ec){ if (!ec) requestTimes_.pop(); });
            }

            requestTimes_.push(now);
            return true;
        } else {
            std::cerr << "Failed to log due to rate limit\n";
            return false;
        }
    }
};

class TestLoggingService : public LoggingService {
public:
    bool LogSensorReading(const TemperatureSensorReading& reading) override {
        // simulate successful logging by returning true.
        std::cout << "Successfully logged sensor reading\n";
        return true;
    }
};
```

