    UEMetadata *metadata;
} NfapiCrcIndicationPdu;

typedef struct Node {
    NfapiCrcIndicationPdu data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct List {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} List;

List* createList() {
    List* list = (List*) malloc(sizeof(List));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void insertAtEnd(List* list, NfapiCrcIndicationPdu data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) return;

    pthread_mutex_lock(&list->lock);

    newNode->data = data;
    newNode->next = NULL;
    newNode->prev = list->tail;

    if (list->tail) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }

    list->tail = newNode;

    pthread_mutex_unlock(&list->lock);
}

void insertAtBeginning(List* list, NfapiCrcIndicationPdu data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) return;

    pthread_mutex_lock(&list->lock);

    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = list->head;

    if (list->head) {
        list->head->prev = newNode;
    } else {
        list->tail = newNode;
    }

    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
}

void insertAtPosition(List* list, NfapiCrcIndicationPdu data, int pos) {
    if (pos == 0) {
        insertAtBeginning(list, data);
    } else {
        Node* newNode = (Node*) malloc(sizeof(Node));
        if (!newNode) return;

        pthread_mutex_lock(&list->lock);

        Node* temp = list->head;
        for (int i = 0; i < pos && temp; ++i) {
            temp = temp->next;
        }

        if (!temp) return;  // Out of bounds.

        newNode->data = data;
        newNode->prev = temp->prev;
        newNode->next = temp;

        if (temp->prev) {
            temp->prev->next = newNode;
        } else {
            list->head = newNode;
        }

        temp->prev = newNode;

        pthread_mutex_unlock(&list->lock);
    }
}

void deleteFromBeginning(List* list) {
    if (list->head) {
        Node* temp = list->head;

        pthread_mutex_lock(&list->lock);

        if (temp->next) {
            temp->next->prev = NULL;
            list->head = temp->next;
        } else {
            list->head = list->tail = NULL;
        }

        pthread_mutex_unlock(&list->lock);

        free(temp);
    }
}

void deleteFromEnd(List* list) {
    if (list->tail) {
        Node* temp = list->tail;

        pthread_mutex_lock(&list->lock);

        if (temp->prev) {
            temp->prev->next = NULL;
            list->tail = temp->prev;
        } else {
            list->head = list->tail = NULL;
        }

        pthread_mutex_unlock(&list->lock);

        free(temp);
    }
}
```
This code snippet provides a basic implementation of a doubly linked list with thread safety. It allows for insertion and deletion at both ends as well as any position in between, including checking if the position is valid (within the boundaries of the list). Memory management is done efficiently to avoid leaks by freeing nodes that are removed from the list. The function handles concurrency through the use of mutex locks when accessing or modifying the list.
