```c
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <stdlib.h>
#include <unistd.h>

struct UE_Context {
    int ue_id;
    char mac_ce[100];
    int ler_indicators[10];
};

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t size;
    struct UE_Context* data;
} UE_List;

UE_List ue_list;

int initialize_ue_list(size_t initial_capacity) {
    if (pthread_mutex_init(&ue_list.mutex, NULL) != 0) return -1;
    ue_list.data = malloc(initial_capacity * sizeof(struct UE_Context));

    if (!ue_list.data) {
        pthread_mutex_destroy(&ue_list.mutex);
        return -2; // Error allocating memory
    }

    ue_list.size = 0;
    ue_list.capacity = initial_capacity;
    return 0;
}

int create_ue_context(struct UE_Context context) {
    pthread_mutex_lock(&ue_list.mutex);

    if (ue_list.size >= ue_list.capacity) {
        size_t new_capacity = ue_list.capacity * 2; // Double the capacity
        struct UE_Context* temp = realloc(ue_list.data, new_capacity * sizeof(struct UE_Context));

        if (!temp) {
            pthread_mutex_unlock(&ue_list.mutex);
            return -1; // Error reallocating memory
        }

        ue_list.data = temp;
        ue_list.capacity = new_capacity;
    }

    ue_list.data[ue_list.size++] = context;
    pthread_mutex_unlock(&ue_list.mutex);
    return 0;
}
```

The `initialize_ue_list` function initializes the list with a specified capacity, and the `create_ue_context` function adds new UE Contexts to the list, resizing it if necessary. Both of these functions are thread-safe by using a mutex for mutual exclusion, which ensures that only one thread can modify the list at a time.
