["Here is an example of how you can implement this function using pthreads for thread safety and error handling mechanisms with errno for system errors. Note that this is a simplified version of the function and does not include all requested features:

```c
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

typedef struct {
    // Add your structure members here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *list;
    pthread_mutex_t mutex;
} List;

List* createList(size_t initialCapacity) {
    if (initialCapacity <= 0) {
        errno = EINVAL; // Invalid argument error
        return NULL;
    }

    List *list = malloc(sizeof(List));
    if (list == NULL) {
        return NULL;
    }

    list->capacity = initialCapacity;
    list->size = 0;
    list->list = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->list == NULL) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void addToList(List *list, NFAPI_CRC_INDICATION_PDU_T item) {
    if (list == NULL || &item == NULL) {
        errno = EINVAL; // Invalid argument error
        return;
    }

    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        list->capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T *newList = realloc(list->list, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newList == NULL) {
            pthread_mutex_unlock(&list->mutex);
            return; // Failed to resize the list
        }

        list->list = newList;
    }

    list->list[list->size] = item;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
}

void freeList(List *list) {
    if (list == NULL) {
        errno = EINVAL; // Invalid argument error
        return;
    }

    pthread_mutex_lock(&list->mutex);

    free(list->list);
    list->capacity = 0;
    list->size = 0;

    pthread_mutex_unlock(&list->mutex);

    pthread_mutex_destroy(&list->mutex);
    free(list);
}
```
