extern bool get_ue_tags(int rnti, uint8_t* tag); 
extern bool get_rntis(uint16_t *rntis, size_t length); 

#define MAX_CACHE_SIZE 1000
typedef struct {
    int rnti;
    uint8_t ue_tag[];
} CachedItem;

// Assume global variables for cache and mutex
static CachedItem* cache[MAX_CACHE_SIZE] = {NULL};
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
atomic_int next_cache_idx = 0;

void add_to_cache(int rnti, uint8_t* ue_tag) {
    pthread_mutex_lock(&cache_lock);

    // Find an empty slot in cache
    int idx = atomic_fetch_add(&next_cache_idx, 1) % MAX_CACHE_SIZE;
    if (cache[idx] != NULL) {
        free(cache[idx]);
    }

    CachedItem* item = malloc(size_t(item));
    memcpy(&item->rnti, &rnti, sizeof(int));
    memcpy(item->ue_tag, ue_tag, sizeof(uint8_t));

    cache[idx] = item;

    pthread_mutex_unlock(&cache_lock);
}

CachedItem* find_in_cache(int rnti) {
    for (int i = 0; i < MAX_CACHE_SIZE; ++i) {
        if (cache[i] != NULL && cache[i]->rnti == rnti) {
            return cache[i];
        }
    }

    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu_list(size_t N, uint8_t *crctags) {
