    for (size_t i = 0; i < N; ++i) {
        int rnti = rntis[i];

        CachedItem* cached = find_in_cache(rnti);
        if (!cached) {
            // Fetch UE tag from data source and cache it
            uint8_t ue_tag;
            if (get_ue_tags(rnti, &ue_tag)) {
                add_to_cache(rnti, &ue_tag);
                cached = find_in_cache(rnti); // Find the item in cache after adding
            }
        }

        if (cached) {
            // Populate the PDU list
            NFAPI_CRC_INDICATION_PDU_T* pdu = &pdus[i];
            memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));

            // ... fill in the PDU as per your requirement using cached->ue_tag and rnti
        }
    }

    return pdus;
}
