                Ok(data) => return Ok(data),
                Err(_) => continue,
            },
            Err(e) if e.is_timeout() || e.is_connect_timeout() || e.is_tls() => {
                std::thread::sleep(Duration::from_secs(1));
                continue;
            }
            Err(_) => return Err(anyhow::Error::msg("Failed to fetch data.")),
        };
    }
}
```
