} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

NFAPI_CRC_INDICATION_PDU_T create_element(RX_UE_INFORMATION_TAG rx, RNTI rnti) {
