    elem.crc_ind_rel8.CRCFLAG = crcflag;

    return elem;
}

void add_element(RX_UE_INFORMATION_TAG rx, RNTI rnti) {
    pthread_mutex_lock(&lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if(new_node == NULL) {
        // Handle memory allocation failure.
        pthread_mutex_unlock(&lock);
        return;
    }

    new_node->data = create_element(rx, rnti);
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&lock);
}
```
This code creates a linked list with thread safety by using a mutex lock. The `add_element` function is responsible for adding an element to the list in a thread-safe manner. 

