ListAndErrorResult createNFAPIPDUs(int N) {
    if (N <= 0) return (ListAndErrorResult){ .errorCode = ERR_INVALID_N };

    srand(time(NULL)); // Seed the random number generator

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);

    if (list == NULL) return (ListAndErrorResult){ .errorCode = ERR_MEMORY_ALLOCATION };

    // Assumes an external function exists to fetch RX_UE_INFORMATION_TAG from external source
    EXTERN_FUNC(int, getNextRxInfo)(&list[0].rxInfo);

    int rntiGenerationResult = ERR_SUCCESS;
    for (size_t i = 1; i < N; ++i) {
        RNTI newRnti;
        if ((rntiGenerationResult = getNextRntiTag(&newRnti)) != ERR_SUCCESS) break; // Duplicate or other error

        int j = 0;
        while (j < i && list[j].rnti.value == newRnti.value) ++j;

        if (j < i) {  // Duplicate found, retry with a different RNTI
            --i;
            continue;
        }

        list[i].rnti = newRnti;
        list[i].crcTag.CRCFLAG = rand() % 2;  // Randomly set CRCFLAG
    }

    if (rntiGenerationResult != ERR_SUCCESS) {
        free(list);
        return (ListAndErrorResult){ .errorCode = rntiGenerationResult };
    }

    return (ListAndErrorResult){ .errorCode = ERR_SUCCESS, .list = list, .count = N };
}
