        if (!node) {
            fprintf(stderr, "Failed to allocate memory for NFAPI_CRC_INDICATION_LIST_T.\n");
            free(pdu); // Free the previously allocated memory.
            pthread_mutex_unlock(&listMutex);
            return NULL; 
        }

        node->pdu = pdu;
        node->next = NULL;

        if (prev) {
            prev->next = node;
        } else { // First node.
            listHead = node;
        }
        prev = node;
    }

    pthread_mutex_unlock(&listMutex); 
    return listHead ? listHead->pdu : NULL; 
}
