#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

// Forward declaration of PHICH Symbol structure
typedef struct PhichSymbol {
    bool crc_flag;
} PhichSymbol;

typedef struct Pdu {
    int ueId;
    bool phichIndicator;
    PhichSymbol *phichSymbol;
} Pdu;

// Global variables for thread safety and memory management
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Pdu **pdus;
int size = 0;
int capacity = 10;

void *generatePhichSymbol() {
    PhichSymbol *symbol = (PhichSymbol *)malloc(sizeof(PhichSymbol));

    if (symbol == NULL) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    symbol->crc_flag = /* predefined rules derived from network configuration parameters */ ;

    return symbol;
}

void *addPdu(int ueId, bool phichIndicator) {
    pthread_mutex_lock(&lock);

    // Resize if necessary
    if (size >= capacity) {
        capacity *= 2;

        Pdu **new_pdus = realloc(pdus, sizeof(Pdu *) * capacity);

        if (new_pdus == NULL) {
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        pdus = new_pdus;
    }

    Pdu *pdu = (Pdu *)malloc(sizeof(Pdu));

    if (pdu == NULL) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Initialize new PDU with valid UE IDs and PHICH Indicators from an external database
    pdu->ueId = ueId;
    pdu->phichIndicator = phichIndicator;

    PhichSymbol *symbol = generatePhichSymbol();

    if (symbol == NULL) {
        free(pdu);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    pdu->phichSymbol = symbol;
    pdus[size++] = pdu;

    pthread_mutex_unlock(&lock);
    return pdu;
}
```
This code is a very basic example and lacks many features you might want to add in a real-world application, such as data retrieval from an external database, error checking for the generation of PHICH Symbols, and more robust memory management. Also, the `generatePhichSymbol` function just sets a placeholder value for the CRC flag. You would need to fill this in with your predefined rules derived from network configuration parameters.
