["Here's a simple implementation using a linked list as data structure with bulk memory allocation. This solution uses mutexes to ensure synchronization on the update function to avoid race conditions. The cleanup mechanism simply iterates over the list and frees memory for unused contexts, while allowing operations on in-use UE contexts to continue without disruption:

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

struct LTE_UE_Context {
    int ue_id;
    int cell_id;
    float snr;
    int cqi;
    struct LTE_UE_Context *next;
};

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int populate_ue_contexts(int num_contexts, struct LTE_UE_Context **ue_list) {
    srand(time(NULL));
    *ue_list = (struct LTE_UE_Context*)malloc(num_contexts * sizeof(struct LTE_UE_Context));
    if (*ue_list == NULL) return -1;

    struct LTE_UE_Context *node = *ue_list;
    for (int i = 0; i < num_contexts; i++, node++) {
        node->ue_id = i+1; // Set a unique UE ID
        node->cell_id = rand() % 5 + 1; // Random cell id between 1 and 5
        node->snr = ((float)rand())/RAND_MAX * 10; // Random signal to noise ratio between 0.0 and 10.0
        node->cqi = rand() % 16; // Random CQI between 0 and 15
        node->next = (i < num_contexts - 1) ? (node + 1): NULL; // Link the nodes together in a linked list.
    }
    return 0;
}

int update_cqi(int ue_id, int new_cqi, struct LTE_UE_Context *ue_list) {
    pthread_mutex_lock(&mutex);

    for (struct LTE_UE_Context* node = ue_list; node != NULL; node = node->next){
        if(node->ue_id == ue_id){
            node->cqi = new_cqi;

            pthread_mutex_unlock(&mutex);
            return 0; // UE context found and updated.
        }
    }

    pthread_mutex_unlock(&mutex);
    return -1; // No matching UE context found.
}

void cleanup_ue_list(struct LTE_UE_Context *ue_list) {
    free(ue_list);
}
```
Please note that this implementation assumes there's no need for real-time updates from external data sources or performance constraints are not a concern. If such requirements exist, consider using a different data structure like a hash table, dynamic memory allocation and deallocation strategies based on the expected number of contexts and update frequency, and additional synchronization mechanisms to manage race conditions.
"]

