int getRandomNumber(int min, int max){
    return rand() % (max - min + 1) + min;
}

// Function to create and populate list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generateList(int n, int *errorCode){
