['Here's a simple implementation of the task in C language using pthread library for thread safety and queue data structure (from stdlib) for efficient access of UE Context structures. The function also checks memory allocation failures and logs errors. It doesn't handle the configuration file part as it depends on the format of the input, the PDU Session Resources are assumed to be an array of integers which can be changed according to need. 

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

// Structure to store UE Context data
typedef struct {
    int IMSI;
    int RNTI;
    int PDU_Session[10]; // Assuming that a UE can have upto 10 sessions
} UEContext;

// Node for queue implementation
typedef struct QueueNode {
    UEContext* data;
    struct QueueNode* next;
} QueueNode;

// Structure to maintain list of UE Contexts
typedef struct {
    QueueNode *front, *rear;
    pthread_mutex_t mutex;
    int size;
} UEContextQueue;

UEContextQueue* createAndPopulate(int num) {
    UEContextQueue* queue = (UEContextQueue*)malloc(sizeof(UEContextQueue));
    if (!queue) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Initialize mutex
    pthread_mutex_init(&(queue->mutex), NULL);
    queue->front = queue->rear = NULL;
    queue->size = 0;

    for (int i=0; i<num; ++i) {
        UEContext* context = (UEContext*)malloc(sizeof(UEContext));
        if (!context) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }

        // Populate with random values. Ensure unique IMSI and RNTI by incrementing them.
        context->IMSI = i + 1; 
        context->RNTI = i + 1;

        for (int j = 0; j < 10; ++j) {
            // Assuming that active flag can be set randomly with a probability of 50%
            context->PDU_Session[j] = rand() % 2 == 0 ? 1 : 0;
        }

        pthread_mutex_lock(&(queue->mutex));
        QueueNode* temp = (QueueNode*)malloc(sizeof(QueueNode));
        if (!temp) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        temp->data = context;
        temp->next = NULL;

        // If queue was empty, then new node is both front and rear.
        if (queue->rear == NULL) {
            queue->front = queue->rear = temp;
        } else {
            // Add the new node at the end of queue and change rear
            queue->rear->next = temp;
            queue->rear = temp;
        }
        ++queue->size;
        pthread_mutex_unlock(&(queue->mutex));
    }

    return queue;
}
```
This function creates a list of UE Contexts and populates it with valid UE Identity (IMSI), Radio Network Temporary Identifier (RNTI) and randomly set active flag states. Each UE has up to 10 PDU sessions which are represented as integers in an array, each being either '0' or '1'. The function also checks for memory allocation failures and logs errors. It uses a mutex for thread safety when accessing the list of UE Contexts. 

