#define INITIAL_SIZE 100
#define GROWTH_FACTOR 2
#define MAX_RETRIES 5

typedef struct {
    pthread_mutex_t mutex;
    atomic_int size;
    lte_phy_layer_pdu* list;
} threadsafe_list;

void init_list(threadsafe_list* list) {
    pthread_mutex_init(&list->mutex, NULL);
    atomic_store(&list->size, 0);
    list->list = malloc(INITIAL_SIZE * sizeof(lte_phy_layer_pdu));
}

void add_to_list(threadsafe_list* list, lte_phy_layer_pdu element) {
    pthread_mutex_lock(&list->mutex);

    int currentSize = atomic_load(&list->size);

    if (currentSize >= INITIAL_SIZE * GROWTH_FACTOR) {
        list->list = realloc(list->list, currentSize * GROWTH_FACTOR * sizeof(lte_phy_layer_pdu));
    }

    list->list[currentSize] = element;
    atomic_fetch_add(&list->size, 1);

    pthread_mutex_unlock(&list->mutex);
}

