// Function to add a new node at the end of the linked list
void append(Node** head, LTE_PHY_RX_INDICATION indication) {
    // Create new node
    Node* new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        exit(-1);  // Failed to allocate memory
    }
