    new_node->next = NULL;

    // If linked list is empty, make the new node as head
    if (*head == NULL) {
       *head = new_node;
       return;
    }

    // Else traverse till end and append new_node
    Node* last = *head;
    while (last->next != NULL) {
        last = last->next;
    }

    last->next = new_node;
}

// Function to process an array of indications, add them to a linked list and update stats.
int processIndicators(LTE_PHY_RX_INDICATION* array, int length, Node** head, int* totalCount, float* avgSignalQuality) {
    // Validate inputs
    if (array == NULL || length == 0) return -1;

    *totalCount = 0;
    *avgSignalQuality = 0.0f;

    for (int i = 0; i < length; ++i) {
        // Add indications to the linked list
        append(head, array[i]);

        // Update total count and signal quality stats
        ++(*totalCount);
        *avgSignalQuality += array[i].CRC_status;  // Dummy calculation for simplicity. Replace with actual processing.
    }

    if (*totalCount > 0) {
        *avgSignalQuality /= *totalCount;
    }

    return 0;
}
