    *newEntry = fetchData(source);
    memUsage += sizeof(*newEntry);

    pthread_mutex_lock(&lock);  // Acquire lock to prevent concurrent access.

    if (memUsage > MEMORY_LIMIT) {
        // If memory usage exceeds limit, remove oldest entries until we are under the limit again.
        while (entryCount > 0 && memUsage > MEMORY_LIMIT) {
            entryCount--;
            free(entries[entryCount]);  // Free the oldest entry.
            memUsage -= sizeof(*newEntry);  // Adjust memory usage accordingly.
        }
    } else if (entryCount < MAX_ENTRIES) {
        // If we have room in our list, add new entry to the end of the list.
        entries = realloc(entries, (entryCount + 1) * sizeof(*newEntry));
        memcpy(&entries[entryCount], newEntry, sizeof(*newEntry));  // Copy data into list.
        free(newEntry);  // Free unnecessary memory allocated for the new entry.
    } else {
        free(newEntry);  // If no room in our list and we're already at limit, simply discard the new entry.
        LOG_ERROR("Maximum number of entries exceeded");
    }

    pthread_mutex_unlock(&lock);  // Release lock to allow other threads to access the function concurrently.
