    int len = 0;
    while(pdu_list[len].ue_index != 0 && pdu_list[len].pdcp_sn != 0) ++len; 

    for(int i = len; i > 0; --i) { // Shift all elements to the right
        pdu_list[i] = pdu_list[i-1];
