void insert_pdcp_pdu(LTE_PDCP_PDU* pdu_list, int index, LTE_PDCP_PDU new_pdu) {
    assert(pdu_list != NULL); // Check if list is not null
    assert(index >= 0 && index < MAX_PDUS); // Ensure valid index

    for(int i = MAX_PDUS-1; i > index; --i) { // Shift all elements to the right from index
        pdu_list[i] = pdu_list[i-1];
