    if (list == NULL) return NULL;

    // Populate the list from the file
    fp = fopen(filename, "r");
    if (fp == NULL) { free(list); return NULL; }

    int i = 0;
    while (fscanf(fp, "%d,%d", &(list[i].UEID), &(list[i].PCI)) == 2) {
        list[i++].PhyCtrlInfo = getRandomModulationScheme();
    }

    fclose(fp);

    return list;
}
