struct hash_table_entry {
    int key;
    void *value;
    struct hash_table_entry *next;
};

typedef struct hash_table {
    int size;
    pthread_mutex_t lock;
    struct hash_table_entry **entries;
} HashTable;

HashTable *hash_table_create(int size) {
    assert(size > 0);

    HashTable *ht = malloc(sizeof(HashTable));
    if (ht == NULL) return NULL;

    ht->entries = calloc((size_t) size, sizeof(struct hash_table_entry*));
    if (ht->entries == NULL) {
        free(ht);
        return NULL;
    }

    ht->size = size;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void hash_table_insert(HashTable *ht, int key, void* value) {
    struct hash_table_entry *entry = malloc(sizeof(*entry));

    assert(entry != NULL);
    entry->key = key;
    entry->value = value;

    pthread_mutex_lock(&ht->lock);

    struct hash_table_entry *next = ht->entries[key % ht->size];
    while (next != NULL) {
        next = next->next;
    }
    next = entry;

    pthread_mutex_unlock(&ht->lock);
}

void* hash_table_get(HashTable *ht, int key) {
    struct hash_table_entry *entry = ht->entries[key % ht->size];
    while (entry != NULL && entry->key != key) {
        entry = entry->next;
    }

    return (entry == NULL ? NULL : entry->value);
}

struct list_node *create_ue_contexts(int N, int hashTableSize) {
    HashTable *ht = hash_table_create(hashTableSize);
    assert(ht != NULL);

