            pdu->rssi[j] = -127.0f + ((float)rand() / RAND_MAX) * 128.0f; // Add validation for RSSI range here
        }

        list[i] = pdu;
    }

    return list;
}

void freeList(PDU** list, int numPDUs) {
    if (!list) {
        return;
    }

    for (int i = 0; i < numPDUs; ++i) {
        PDU* pdu = list[i];

        if (pdu) {
            free(pdu->rssi);
            free(pdu);
        }
    }

    free(list);
}

int comparePDUs(const void* a, const void* b) {
    PDU** pduA = (PDU**)a;
    PDU** pduB = (PDU**)b;

    return (*pduA)->time_slot_index - (*pduB)->time_slot_index;
}

void sortPDUs(PDU** list, int numPDUs, int ascending) {
    qsort(list, numPDUs, sizeof(PDU*), comparePDUs);

    if (!ascending) {
        for (int i = 0; i < numPDUs / 2; ++i) {
            PDU* temp = list[i];
            list[i] = list[numPDUs - i - 1];
            list[numPDUs - i - 1] = temp;
        }
    }
}

float calculateAverageRSSI(PDU* pdu, int numRSSIValues) {
    float sum = 0.0f;

    for (int i = 0; i < numRSSIValues; ++i) {
        sum += pdu->rssi[i];
    }

    return sum / numRSSIValues;
}
```
