void resize() {
    if(size == capacity) {
        capacity *= 2;
        list = realloc(list, sizeof(LTEPHYControlInfo)*capacity);
    }
}

void serializeList() {
    file = fopen(filename, "wb");
    for(int i = 0; i < size; i++) {
        fwrite(&list[i], sizeof(LTEPHYControlInfo), 1, file);
    }
    fclose(file);
}

void deserializeList() {
    file = fopen(filename, "rb");
    if(file == NULL) {
        printf("Error opening file\n");
        exit(-1);
    }

    LTEPHYControlInfo tmp;
    while(fread(&tmp, sizeof(LTEPHYControlInfo), 1, file)) {
        resize();
        list[size++] = tmp;
    }
    fclose(file);
}

void addEntryToList(char UEID[20], int PCI, int NCS, int TPC) {
    if(!list){
        list = malloc(capacity*sizeof(LTEPHYControlInfo));
