    if (newNode->data == NULL) {
        free(newNode);
        return; // handle allocation failure
    }

    newNode->data->ueId = ueId;
    newNode->data->rnti = rnti;
    newNode->data->downlinkMacPdu = downlinkMacPdu;
    newNode->data->crcFlag = crcFlag;

    pthread_mutex_lock(&lock); // lock to ensure thread safety

    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void removeUE(int ueId) {
    if (head == NULL) return;

    pthread_mutex_lock(&lock); // lock to ensure thread safety

    ListNode *temp = head, *prev = NULL;

    while (temp != NULL && temp->data->ueId != ueId) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // UE not found
    else if(prev != NULL) prev->next = temp->next;

    if(temp == head) head = head->next;

    free(temp->data);
    free(temp);

    pthread_mutex_unlock(&lock);
}

void validateUE() {
    ListNode *temp = head;

    while (temp != NULL) {
        // implement validation logic here, e.g., check if fields are within expected ranges

        temp = temp->next;
    }
}
