    srand(time(NULL));
    for (int i = 0; i < CACHE_SIZE; ++i) {
        cache[i] = malloc(sizeof(LteUeContext));
        cache[i]->macCe = rand();
        cache[i]->lerIndicator = ((float)rand()/(float)(RAND_MAX)) * 10;
    }
