#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct tcp_connection {
    int connID;
    char remoteIP[16];
    int remotePort;
    time_t timestamp;
    void* buffer;  // Pointer to data packet buffer
    size_t bufSize;

    pthread_mutex_t mutex;
    struct tcp_connection *next;
} TCPConnection;

typedef struct {
    TCPConnection *head;
    pthread_mutex_t mutex;  // To protect head and tail modifications
} ConnectionList;

TCPConnection* createNewConnection(int connID, char* remoteIP, int remotePort) {
    if (connID <= 0 || !remoteIP || remotePort <= 0) return NULL;  

    TCPConnection *newConn = malloc(sizeof(TCPConnection));
    if (!newConn) return NULL;  // Check allocation error

    newConn->connID = connID;
    strncpy(newConn->remoteIP, remoteIP, sizeof(newConn->remoteIP)-1);
    newConn->remotePort = remotePort;
    newConn->timestamp = time(NULL);   // Set current time

    pthread_mutex_init(&newConn->mutex, NULL);  // Initialize mutex for thread safety

    return newConn;
}

int addConnectionToList(TCPConnection *conn, ConnectionList *list) {
    if (!conn || !list) return -1;  // Check null pointers

    pthread_mutex_lock(&list->mutex);   // Lock the list to prevent race condition
    conn->next = list->head;
    list->head = conn;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}
```
