#include <arpa/inet.h>
#include <sys/socket.h>

typedef struct {
    char* imsi;
    int messageType;
    size_t length;
} NASMessage;

int sendMessages(char** imsis, size_t numIMSIs) {
    if (!imsis || numIMSIs == 0) return 0; // handle cases where database is down or returns no results

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in servAddr;
    memset(&servAddr, '0', sizeof(servAddr));
    servAddr.sin_family = AF_INET;
    servAddr.sin_port = htons(5000); // base station port
    inet_pton(AF_INET, "127.0.0.1", &servAddr.sin_addr); // base station IP address

    NASMessage* messages[numIMSIs];
    for (size_t i = 0; i < numIMSIs; ++i) {
        messages[i] = malloc(sizeof(NASMessage));
        messages[i]->imsi = imsis[i];
        messages[i]->messageType = rand() % 256; // random message type
        messages[i]->length = 0; // additional field for message length, not used in this example
    }

    int retriesLeft = 3;
    while (retriesLeft > 0) {
        ssize_t sentBytes = sendto(sockfd, messages, sizeof(messages), 0, (struct sockaddr*)&servAddr, sizeof(servAddr));

        if (sentBytes < 0) {
            perror("Failed to send message");
            --retriesLeft;

            // Wait a bit before retrying to avoid spamming the network in case of temporary issues
            sleep(1);
        } else {
            break;
        }
    }

    if (retriesLeft == 0) {
        perror("Failed to send message after multiple attempts");
        close(sockfd);
        for (size_t i = 0; i < numIMSIs; ++i) free(messages[i]);

        return -1;
    }

    // Clean up memory allocation
    close(sockfd);
    for (size_t i = 0; i < numIMSIs; ++i) free(messages[i]);

    return 0;
}
```
