} Request;

typedef struct {
    int capacity;
    int size;
    Request *requests;
} ListOfRequests;

ListOfRequests* createListOfRequests(int initialSize) {
    ListOfRequests *list = malloc(sizeof(ListOfRequests));
    if (list == NULL) {
        printf("Memory allocation failed");
        exit(1);
    }
    list->requests = calloc(initialSize, sizeof(Request));
    if (list->requests == NULL) {
        printf("Memory allocation failed");
        free(list);
        exit(1);
    }
    list->capacity = initialSize;
    list->size = 0;
    return list;
}

void addRequestToList(ListOfRequests *list, Request request) {
    if (list->size == list->capacity) {
        list->requests = realloc(list->requests, sizeof(Request) * list->capacity * 2);
        if (list->requests == NULL) {
            printf("Memory allocation failed");
            exit(1);
        }
        list->capacity *= 2;
    }
    memcpy(&list->requests[list->size], &request, sizeof(Request));
    list->size++;
}

void serializeListToFile(char *filename, ListOfRequests *list) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Could not open file for writing\n");
        return;
    }

    for (int i = 0; i < list->size; i++) {
        Request *request = &list->requests[i];
        fprintf(fp, "URL: %s\n", request->url);
        fprintf(fp, "Method: %s\n", request->method);
        for (int j = 0; j < request->numHeaders; j++) {
            fprintf(fp, "Header: %s\n", request->headers[j]);
        }
    }

    fclose(fp);
}

void freeListOfRequests(ListOfRequests *list) {
    for (int i = 0; i < list->size; i++) {
        Request *request = &list->requests[i];
        free(request->url);
        free(request->method);
        for (int j = 0; j < request->numHeaders; j++) {
            free(request->headers[j]);
        }
        free(request->headers);
    }
    free(list->requests);
    free(list);
}
