int validateRNTI(unsigned long RNTI) {
    CURL* curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return -1;  // Return error code on initialization failure
    }

    char url[256];
    sprintf(url, "http://external-data-source.com/validate?RNTI=%lu", RNTI);
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 500L);

    int retries = 0;
    while (1) {
        CURLcode res = curl_easy_perform(curl);
        ++retries;
        if (res != CURLE_OK && retries < MAX_RETRIES) {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);

            // Handle potential network failures
            if (response_code >= 500 && response_code < 600) {  // Server error
                continue;  // Retry on server errors
            } else {
                break;  // Break on other errors
            }
        } else {
            break;  // Success or max retries reached, break the loop
        }
    }

    curl_easy_cleanup(curl);

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to validate RNTI after %d retries\n", MAX_RETRIES);
        return -1;  // Return error code on failure
    } else {
        return 0;  // Return success code on successful validation
    }
}
