["Here's a basic way to implement this functionality in C with some notes on potential improvements for handling large amounts of data efficiently or dealing with race conditions in a multi-threaded environment:

```c
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RNTI;
    // other fields
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node *head = NULL;
pthread_mutex_t lock;  // for thread safety

int append(NFAPI_CRC_INDICATION_PDU_T value) {
    Node* newNode = malloc(sizeof(Node));

    if (newNode == NULL) return -1;  // error: out of memory

    srand(time(NULL));
    do {
        value.RNTI = rand() % UINT16_MAX; // generate random RNTI
    } while (!isUnique(value.RNTI)); // check uniqueness

    newNode->data = value; 
    newNode->next = NULL;

    pthread_mutex_lock(&lock); // lock to prevent race condition
    if (head == NULL) {
        head = newNode;
    } else {
        Node* temp = head;
        while(temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    pthread_mutex_unlock(&lock); // unlock

    return 0;
}

bool isUnique(uint16_t RNTI) {
    Node* temp = head;
    while (temp != NULL) {
        if (temp->data.RNTI == RNTI) return false; // duplicate found
        temp = temp->next;
    }
    return true; // no duplicates found
}
```

This code uses a linked list and pthread mutex lock to ensure thread safety when appending new elements. The `isUnique` function checks the current list for any duplicate RNTI values before allowing it to be added, reducing the chance of creating non-unique RNTIs. It's worth mentioning that using srand with time(NULL) might not generate enough random numbers in a short span of time and this would lead to less unique RNTIs than expected if function is called multiple times in a second. A more sophisticated random number generator may be needed for better performance. Also, using malloc and free functions are used which can consume significant resources especially with large data sets. Using a memory pool or other dynamic allocation techniques could reduce this cost but would require extra development work.
