typedef struct MAC_HEADER {
    /* Add fields as necessary */
} MAC_HEADER;

typedef struct SDU {
    /* Add fields as necessary */
} SDU;

typedef struct MAC_PDU {
    MAC_HEADER header;
    SDU *sdus; // An array of SDUs, with a fixed size
    int num_sdus;
    time_t timestamp;
    int priority;
    struct MAC_PDU *next;  // For linked list implementation
} MAC_PDU;

MAC_PDU* create_mac_pdu(MAC_HEADER header, SDU *sdus, int num_sdus, int priority) {
    if (header == NULL || sdus == NULL || num_sdus <= 0) return NULL;

    MAC_PDU *new_node = malloc(sizeof(MAC_PDU));
    new_node->header = header;
    new_node->sdus = sdus;  // Shallow copy, you might want to deep copy depending on your needs
    new_node->num_sdus = num_sdus;
    time(&(new_node->timestamp));
    new_node->priority = priority;
    new_node->next = NULL;

    return new_node;
}

void add_mac_pdu(MAC_PDU **head, MAC_HEADER header, SDU *sdus, int num_sdus, int priority) {
    if (header == NULL || sdus == NULL || num_sdus <= 0) return;

    MAC_PDU *new_node = create_mac_pdu(header, sdus, num_sdus, priority);
    new_node->next = *head;
    *head = new_node;
}

void remove_mac_pdu(MAC_PDU **head, MAC_HEADER header) {
    if (*head == NULL || header == NULL) return;

    MAC_PDU *temp = *head, *prev = NULL;

    if (temp != NULL && temp->header.comparator(header)) {
        *head = temp->next;   // Changed head
        free(temp);           // Free old head
        return;
    }

    while (temp != NULL && !temp->header.comparator(header)) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;  // header was not present in the list

    prev->next = temp->next;  // Unlink the node from linked list
    free(temp);               // Free memory
}

void traverse_mac_pdu_list(MAC_PDU *node) {
    while (node != NULL) {
        // You can perform operations on each node here
        node = node->next;
    }
}

void free_mac_pdu_list(MAC_PDU **head) {
    MAC_PDU *current = *head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL; // Set head to NULL to avoid dangling pointers
}
```
