#include <pthread.h>

#define MAX_SIZE 1000
#define HIGH_LOAD_THRESHOLD 800
#define TIMEOUT 5 // seconds

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG {
        int CRCFLAG;
    } CRCI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct listNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp; // used for TTL and rate limiting
    int priority;
    struct listNode *next;
} ListNode;

ListNode* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int currentSize = 0;
time_t lastInsertionTime = 0; // used for rate limiting
extern void notifyHealthMonitoringSystem(void); // external health monitoring system notification function
extern int getDataFromExternalSource(NFAPI_CRC_INDICATION_PDU_T* data, time_t timeout); // function to fetch data from external source

int insertIntoList(NFAPI_CRC_INDICATION_PDU_T data, int priority) {
    if (currentSize >= MAX_SIZE) return -1; // list is full

    pthread_mutex_lock(&mutex); // lock to ensure thread safety

    time_t now = time(NULL);
    double diffInSeconds = difftime(now, lastInsertionTime);

    if (diffInSeconds < 1.0) { // rate limiting
        pthread_mutex_unlock(&mutex);
        return -2;
    }

    lastInsertionTime = now;

    ListNode* newNode = malloc(sizeof(ListNode));
    if (newNode == NULL) {
        logError("Memory allocation failure"); // error handling
        pthread_mutex_unlock(&mutex);
        return -3;
    }

    newNode->data = data; 
    newNode->timestamp = now;
    newNode->priority = priority;
    currentSize++; // increment list size

    if (currentSize > HIGH_LOAD_THRESHOLD) {
        notifyHealthMonitoringSystem();
    }

    // Insertion based on priority
    ListNode **tracer = &head;
    while (*tracer != NULL && (*tracer)->priority <= priority) {
        tracer = &((*tracer)->next);
    }
    newNode->next = *tracer;
    *tracer = newNode;

    pthread_mutex_unlock(&mutex); // unlock mutex after operation

    return 0; // success
}
