["Here's a simple example of how you might implement this using C with `pthread` for thread safety, and dynamic memory allocation for the list itself. Please note that it is highly recommended to use a more sophisticated structure or library (like glib) if your application will handle larger amounts of data and/or have high concurrency requirements:

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;
int count = 0;

void add(NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if(!new_node) {
        pthread_mutex_unlock(&lock);
        return;
    }
    new_node->data = data;
    new_node->next = head;
    head = new_node;
    count++;

    pthread_mutex_unlock(&lock);
}

void remove_all() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while(current) {
        Node* temp = current;
        free(temp->data); // Free data before node, assuming it's dynamically allocated.
        current = current->next;
        free(temp);
    }
    count = 0;

    pthread_mutex_unlock(&lock);
}
```

In this example, the `add` function adds a new item to the list. This function is thread safe because it acquires and releases the lock around the critical section (the part of code where shared data is modified). The `remove_all` function also has similar locking to ensure that the list cannot be accessed while it's being cleared.

