typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* validRNTIs = NULL;  // Initialize list of valid RNTIs with system updates/user configs.
pthread_mutex_t mutexLock = PTHREAD_MUTEX_INITIALIZER;

int validateRNTI(int rnti) {
    pthread_mutex_lock(&mutexLock);
    Node* current = validRNTIs;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&mutexLock);
            return 1;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&mutexLock);
    return 0;
}

void addValidRNTI(int rnti) {
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        exit(-1); // Error handling for out-of-memory condition.
    }
    newNode->data.RNTI = rnti;
    pthread_mutex_lock(&mutexLock);
    newNode->next = validRNTIs;
    validRNTIs = newNode;
    pthread_mutex_unlock(&mutexLock);
}

void removeValidRNTI(int rnti) {
    Node* current = validRNTIs, *prev = NULL;
    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) return; // RNTI not found in list, do nothing.
    pthread_mutex_lock(&mutexLock);
    if (prev != NULL) prev->next = current->next;
    else validRNTIs = current->next;
    free(current);
    pthread_mutex_unlock(&mutexLock);
}

Node* createCRCIndicationList(int N, int* RNTIs) {
    srand(time(NULL)); // Seed the random number generator.
    Node* head = NULL;
    for (int i = 0; i < N; ++i) {
        if (!validateRNTI(RNTIs[i])) continue; // Skip RNTIs not in valid list.
        Node* newNode = malloc(sizeof(Node));
        if (newNode == NULL) {
            exit(-1); // Error handling for out-of-memory condition.
        }
        newNode->data.RNTI = RNTIs[i];
        newNode->next = head;
        head = newNode;
    }
    return head;
}
