    pthread_mutex_lock(&lock);
    Node *newNode = (Node*)malloc(sizeof(Node));
    newNode->UE_ID = UE_ID;
    newNode->PDCCH_Format = PDCCH_Format;
    newNode->CRC_Status = CRC_Status;

    if(head == NULL || head->UE_ID >= newNode->UE_ID) {
        newNode->next = head; 
        newNode->prev = NULL;
        if(head != NULL) {
            head->prev = newNode;
        }
        head = newNode;
    } else {
        Node *current = head;
        while(current->next != NULL && current->next->UE_ID < newNode->UE_ID) {
            current = current->next;
        }
        newNode->next = current->next;
        if(current->next != NULL) {
            current->next->prev = newNode;
        }
        newNode->prev = current; 
        current->next = newNode; 
    }
    pthread_mutex_unlock(&lock);
}

void printList() {
    Node *current = head;
    while(current != NULL) {
        printf("UE ID: %d, PDCCH Format: %d, CRC Status: %d\n", 
               current->UE_ID, current->PDCCH_Format, current->CRC_Status);
        current = current->next;
    }
}

void destroy() {
    Node *current = head;
    while(current != NULL) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }
    head = NULL;
}
``` 
In this code, I have used a doubly linked list with mutex for thread safety. For each new node, I check if the list is empty or if its UE_ID is smaller than the current head's. If so, I simply make it as the head of the list. Otherwise, find the right place to insert this node in sorted order.

For validation from external data sources (like a database or an API), you will need to implement that functionality which depends on your specific needs and is not included here. Also, efficient concurrent removals would require more complex handling, especially for large lists as they can't be traversed concurrently without thread safety mechanisms in place.
