typedef struct {
    int ueID;
    int cellID;
    NeighborCellInfo neighborCells[5]; // up to 5 neighbor cells
} UEContext;

UEContext* createUEContexts(int numOfUEs, FILE* neighborData) {
    if (neighborData == NULL) {
        fprintf(stderr, "Neighbor data source unavailable.\n");
        return NULL;
    }

    UEContext* ueContexts = malloc(numOfUEs * sizeof(UEContext));
    if (ueContexts == NULL) {
        fprintf(stderr, "Memory allocation failed for UE contexts.\n");
        exit(EXIT_FAILURE);
    }

    int ueID;
    while (fscanf(neighborData, "%d", &ueID) == 1) { // validate data before using it
        if (ueID < 0 || ueID >= numOfUEs) {
            fprintf(stderr, "Invalid UE ID: %d\n", ueID);
            continue;
        }

        UEContext* currentUE = &ueContexts[ueID];
        currentUE->ueID = ueID;

        if (fscanf(neighborData, "%d", &currentUE->cellID) != 1) {
            fprintf(stderr, "Failed to read Cell ID for UE %d.\n", ueID);
            continue;
        }

        for (int i = 0; i < 5; ++i) { // up to 5 neighbor cells
            NeighborCellInfo* neighbor = &currentUE->neighborCells[i];

            if (fscanf(neighborData, "%d %f %f", &neighbor->cellID, &neighbor->rsrp, &neighbor->rsrq) != 3) {
                fprintf(stderr, "Failed to read neighbor cell info for UE %d.\n", ueID);
                break;
            }
        }
    }

    return ueContexts;
}
```

