        ue_list[i].cell_id = (i%4) + 1; // Each UE on a different band for this example.

        // Initialize measurement results with dummy values
        for(int j = 0; j < 4; j++){
            ue_list[i].measurement_results[j] = (float)(rand() % 50);
        }
    }

    return ue_list;
}

void* add_ue(ue_context *ue_list, int num_ues, int new_id){

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&lock);

    // Reallocate memory for additional UE context
    ue_list = realloc(ue_list, (num_ues + 1) * sizeof(ue_context));
    if (ue_list == NULL){
        printf("Memory allocation failed.\n");
        exit(-1);
    }

    // Add new UE context with valid IDs and measurements
    ue_list[num_ues].ue_id = new_id;
    ue_list[num_ues].cell_id = (new_id % 4) + 1;

    for(int j = 0; j < 4; j++){
        ue_list[num_ues].measurement_results[j] = (float)(rand() % 50);
    }

    // Unlock the mutex after updating the list
    pthread_mutex_unlock(&lock);

    return ue_list;
}
