#include <assert.h>
#include <time.h>

typedef struct LTE_PHY_RX_FRAMES_T {
    int LTE_PHY_RX_FRAME_TAG;
    int LTE_RNTI;
    int CRCFLAG;
} LTE_PHY_RX_FRAMES_T;

typedef struct Node {
    LTE_PHY_RX_FRAMES_T data;
    struct Node* next;
} Node;

Node* createList(int size) {
    srand(time(0));

    Node *head = NULL, *tail = NULL;
    for (int i = 0; i < size; ++i) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (newNode == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }

        newNode->data.LTE_PHY_RX_FRAME_TAG = i; // Dummy value
        newNode->data.LTE_RNTI = rand() % 100; // Random value between 0 and 99
        newNode->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        if (head == NULL) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    return head;
}

void deleteList(Node** headRef) {
    assert(headRef != NULL);

    Node* current = *headRef;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    *headRef = NULL; // To avoid dangling pointer
}
```
