static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert(Node **head, LTE_RRC_UE_CONTEXT *newContext) {
    pthread_mutex_lock(&lock); // Acquire lock for thread safety
    Node* newNode = (Node*) malloc(sizeof(Node));
    if(!newNode) exit(-1); 
    newNode->data = newContext; 
    newNode->next = *head; 
    *head = newNode; 
    pthread_mutex_unlock(&lock); // Release lock
}

void delete(Node **head, LTE_RRC_UE_CONTEXT *target) {
    if(*head == NULL) return;
    Node* temp = *head;
    Node* prev = NULL;
    while(temp != NULL && temp->data != target) { 
        prev = temp; 
        temp = temp->next; 
    }
    if(temp == NULL) return; 
    pthread_mutex_lock(&lock); // Acquire lock for thread safety
    if(prev != NULL) 
        prev->next = temp->next; 
    else
        *head = temp->next; 
    free(temp);
    pthread_mutex_unlock(&lock); // Release lock
}

void updateInactivityTimer(Node **head, LTE_RRC_UE_CONTEXT* context) {
