    uint16_t UE_ID;
    uint8_t RLC_Segment[1024];
    uint8_t CRC_Status;
} UE_Data_T;

extern uint16_t get_external_UE_ID();
extern NFAPI_CRC_INDICATION_PDU_T* get_NFAPI_CRC_INDICATION_PDU();

#define MAX_UES 10000

int initialize_ue_data_array(UE_Data_T *ue_data_array, size_t num_ues) {
