    srand((unsigned int)time(NULL));
    ue_data_array = malloc(num_ues * sizeof(UE_Data_T));
    if (ue_data_array == NULL) return -1; // Return error code for memory allocation failure.

    for (size_t i = 0; i < num_ues; i++) {
        ue_data_array[i].UE_ID = get_external_UE_ID();

        NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication = NULL;
        do {
            nfapi_crc_indication = get_NFAPI_CRC_INDICATION_PDU();

            // If a transient failure occurs, retry with exponential backoff.
            if (nfapi_crc_indication == NULL) { 
                sleep(1 << i); // Exponential backoff delay
            }
        } while(nfapi_crc_indication == NULL && i < 10); // Retry limit of 10 attempts

        if (nfapi_crc_indication != NULL) {
            memset(ue_data_array[i].RLC_Segment, 0, sizeof(ue_data_array[i].RLC_Segment));
            ue_data_array[i].CRC_Status = nfapi_crc_indication->CRCFLAG;
        } else {
            return -1; // Return error code for transient failure after retries.
        }
    }

    return 0; // Successful execution
}
```

