    NFAPI_CRC_INDICATION_PDU_T* head = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (head == NULL) {
        *error = 1; // Memory allocation failed
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* current = head;
    for (int i = 0; i < N - 1; ++i) {
        current->crc_tag = malloc(sizeof(struct CRC_INDICATION_REL8_TAG));
        if (current->crc_tag == NULL) {
            *error = 2; // Memory allocation failed for crc_tag
            return NULL;
        }

        current->RX_UE_INFORMATION_TAG = i + 1;
        current->RNTI = rand();
        int isCritical = 0;
        for (int j = 0; j < sizeof(criticalRNTIs) / sizeof(int); ++j) {
            if (current->RNTI == criticalRNTIs[j]) {
                isCritical = 1;
                break;
            }
        }

        current->crc_tag->CRCFLAG = isCritical ? 1 : 0;

        NFAPI_CRC_INDICATION_PDU_T* newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newNode == NULL) {
            *error = 3; // Memory allocation failed for new node
            return NULL;
        }

        current->next = newNode;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return head;
}
