BandwidthPartConfiguration* create_bw_part_config(int bandwidth) {
    if (bandwidth < 0 || bandwidth > MAX_BW) return NULL;

    BandwidthPartConfiguration* bw = malloc(sizeof(BandwidthPartConfiguration));
    if (!bw) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }
    bw->bandwidth = bandwidth;

    return bw;
}

NetworkConfig* create_network_config(int cell_id, int bandwidths[], size_t num_bws) {
    NetworkConfig* netconf = malloc(sizeof(NetworkConfig));
    if (!netconf) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }
    netconf->cell_id = cell_id;

    BandwidthPartConfiguration** bws = malloc(num_bws * sizeof(BandwidthPartConfiguration*));
    if (!bws) {
        fprintf(stderr, "Memory allocation error\n");
        free(netconf);
        return NULL;
    }

    for (size_t i = 0; i < num_bws; ++i) {
        bws[i] = create_bw_part_config(bandwidths[i]);

        if (!bws[i]) {
            for (size_t j = 0; j < i; ++j) free(bws[j]);

            free(netconf);
            return NULL;
        }
    }

    netconf->bw_configs = bws;
    netconf->num_bw_configs = num_bws;

    return netconf;
}

void destroy_network_config(NetworkConfig* netconf) {
