#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define your structure here
} NFAPI_CRC_INDICATION_PDU;

void* handleConnection(void *arg) {
    int clientSocket = *((int*) arg);
    char buffer[1024];

    if (recv(clientSocket, buffer, 1024, 0) < 0) {
        printf("Receive failed\n");
        return NULL;
    }

    // Parsing and handling POST request goes here.
    // For simplicity, we'll assume you have a function named handlePostRequest:
    // handlePostRequest(buffer, &clientSocket);

    close(clientSocket);
    free(arg);
    return NULL;
}

void startServer() {
    int serverSocket = socket(AF_INET, SOCK_STREAM, 0), clientSocket;
    struct sockaddr_in serverAddress, clientAddress;

    if (serverSocket < 0) {
        printf("Failed to create socket\n");
        return;
    }

    // Setup the server address struct
    bzero((char *) &serverAddress, sizeof(serverAddress));
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_addr.s_addr = INADDR_ANY;
    serverAddress.sin_port = htons(8080); // Listen on port 8080

    if (bind(serverSocket, (struct sockaddr *) &serverAddress, sizeof(serverAddress)) < 0) {
        printf("Failed to bind socket\n");
        return;
    }

    listen(serverSocket, 5); // Allow up to 5 pending connections

    while(1) {
        socklen_t clientLength = sizeof(clientAddress);

        if ((clientSocket = accept(serverSocket, (struct sockaddr *) &clientAddress, &clientLength)) < 0) {
            printf("Failed to accept connection\n");
            continue;
        }

        pthread_t threadId;
        int* clientSocketPtr = malloc(sizeof(*clientSocketPtr));
        *clientSocketPtr = clientSocket;

        if (pthread_create(&threadId, NULL, handleConnection, clientSocketPtr) < 0) {
            printf("Failed to create thread\n");
            return;
        }
    }

    close(serverSocket);
}
``` 

This code creates a basic single-threaded HTTP server that listens for POST requests on port 8080. It creates a new thread for each client connection and passes the socket descriptor to the `handleConnection` function which is responsible for receiving, processing, and closing the client's request.

