    pthread_mutex_t lock;  // declare a mutex lock for thread safety
    if (pthread_mutex_init(&lock, NULL) != 0) {
        perror("Failed to initialize the mutex");
        return NULL;
    }

    for(int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

