        newNode->RNTI = rand();  // populate the RNTI with a random value
        newNode->CRCFLAG = rand() % 2; // set CRCFLAG to either 0 or 1

        pthread_mutex_lock(&lock); // lock the mutex before accessing shared data
        if(head == NULL) {
            head = tail = newNode;
            head->next = NULL;
        } else {
            tail->next = newNode;
            tail = newNode;
            tail->next = NULL;
        }
        pthread_mutex_unlock(&lock); // unlock the mutex after finished accessing shared data
    }

    pthread_mutex_destroy(&lock); // destroy the mutex when it's no longer needed

    return head;
}
