void addToList(int rnti, char crcflag){
    pthread_mutex_lock(&lock);
    if (listSize >= MAX_LIST_SIZE) {
        fprintf(stderr, "List size exceeded. Skipping addition.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->rxUeInformationTag.RNTI = rnti;
