    if (list == NULL) {
        list = newNode;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *curr = list;
        while(curr->next != NULL){
            curr = curr->next;
        }
        curr->next = newNode;
    }
    ++listSize;
    pthread_mutex_unlock(&lock);
}
